(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0018.js"] = [{"id":"poem-75eab0793f72d057da2c9cf2","title":"送元侍御还荆南幕府","author":"李嘉祐","dynasty":"唐","verses":["迢递荆州路，山多水又分。","霜林澹寒日，朔鴈蔽南云。","八座由持节，三湘亦置军。","自当行直指，应不为功勋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c1a00c30-798a-4085-a3c8-bb6dd38b2e61","tags":[]},{"id":"poem-75eeecfc6f39b17fc62649d3","title":"阮郎归·呈郑王十二弟","author":"李煜","dynasty":"五代","verses":["东风吹水日衔山，春来长是闲。","落花狼籍酒阑珊，笙歌醉梦间。","佩声悄，晚妆残，凭谁整翠鬟？","留连光景惜春颜，黄昏独倚栏。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-24","tags":[]},{"id":"poem-75f7e17ad4765ac18ee46d8f","title":"虞美人·曲阑干外天如水","author":"晏几道","dynasty":"宋","verses":["曲阑干外天如水。","昨夜还曾倚。","初将明月比佳期。","长向月圆时候、望人归。","罗衣著破前香在。","旧意谁教改。","一春离恨懒调弦。","犹有两行闲泪、宝筝前。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-33","tags":["宋词三百首"]},{"id":"poem-75f7f6bad939a29d0886d6fa","title":"骥无称筑墙护放生池","author":"释居简","dynasty":"宋","verses":["凿山樊圃幻屏帷，自出胸中一段奇。","拓寿域归常住地，注恩波入放生池。","剪蒿忍放蛙分部，空穴宁教兔不疑。","坐看春风归约勒，先开墙角向南枝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-32074fd6-cdc9-4560-87a4-009fddfddb30","tags":[]},{"id":"poem-75f9275fe8f7f8085b2f5961","title":"招徐鼎臣（题拟）","author":"钟谟","dynasty":"唐","verses":["看看潘鬓二毛生，昨日林梢又转鸎。","欲对春风忘世虑，敢言尊酒召时英。","假中西阁幸无事，筵中南威幸有情。","不得车公终不乐，已教红袖出门迎。","（《徐公文集》卷二。","）（按：《徐公文集》此诗题作《寄钟谟》，其次为《正初答钟郎中见招》，二诗皆用「鸎」、「英」、「情」、「迎」四韵。","详诗意，前诗为春初招人过访之作，后诗为答前诗之作。","因此，前诗应为钟谟作，后诗始为徐铉作。","《全唐诗》卷七五二以二诗皆归徐铉，未允，今为移正。","以上参《文史》二十五期曹汛先生文。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-13cc08d1-6cf1-45d1-a7dd-a43516bed7cf","tags":[]},{"id":"poem-75fd2b54b16959d2b27afd7a","title":"次韵郑教授见寄","author":"李纲","dynasty":"宋","verses":["泛梗飘萍逐水流，故人书到正霜秋。","扶颠拯溺多迂论，问舍求田更拙谋。","辇道凄凉沙碛外，钩陈寂寞楚江头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-86562740-2d14-4236-b931-31a90d561659","tags":[]},{"id":"poem-760acb9ededbf5a9f6b9ff07","title":"入邑阻风  其二","author":"释居简","dynasty":"宋","verses":["见时无事去还思，往往来参去不辞。","弗是山林傲轩冕，澹台有请独无私。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-2ff086b4-6a32-4c7f-af56-cf8a3d45f6e7","tags":[]},{"id":"poem-760f3ebce0e857bcf98b1933","title":"须菩提赞","author":"释了惠","dynasty":"宋","verses":["道个希有世尊，不知口是祸门。","至今看经未了，立得拄杖生根。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-bebd4da3-ef97-4e08-ab2e-705a5de937f2","tags":[]},{"id":"poem-761f6272f073954966682f03","title":"后出塞五首 五","author":"杜甫","dynasty":"唐","verses":["我本良家子，出师亦多门。","将骄益愁思，身贵不足论。","跃马二十年，恐辜明主恩。","坐见幽州骑，长驱河洛昏。","中夜间道归，故里但空邨。","恶名幸脱免，穷老无儿孙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0fa40901-8543-407c-97dc-95d9e3201b85","tags":[]},{"id":"poem-76249ef5c6c8c4070bb32341","title":"戏赠侯常侍","author":"李洞","dynasty":"唐","verses":["葛洪卷与江淹赋，名动天边傲石居。","两蜀词人多载后，同君讳却马相如。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2266386d-8617-44b2-8cd4-49beb4d97e32","tags":[]},{"id":"poem-76256100ffc9d2eaff5e3438","title":"寒栖子歌","author":"皎然","dynasty":"唐","verses":["君在庐山不知群，有疑是鹤又是云。","生死尘埃污不得，眼前荣利徒纷纷。","今日惠然来访我，酒榼书囊肩背荷。","拂除衣上饵烟霞，昨夜胥门宿蔡家。","天然不饮亦不食，抛名换姓觅不得。","且向人间作酒僊，不肯将身生羽翼。","停形为饵天地根，世人皆死我独存。","洗虑因吞清明箓，世人皆贪我常足。","栖子妙今道已成，手把玄枢心运冥。","能令鬼哭神效灵，身如飘风不可绊。","朝游崆峒夕汗漫，向来坐客犹未散。","忽忆罗浮欲去时，遥指孤云作路岐。","海上仙游不可见，人间日落空桑枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-853e4d9d-d1e5-4a68-8432-33048877cc31","tags":["庐山"]},{"id":"poem-7629e68d6e7450f974ac5bac","title":"寒夜有怀同志","author":"贯休","dynasty":"唐","verses":["永夜殊不寐，怀君正寂寥。","疎钟寒徧郭，微雪静鸣条。","南省鴈孤下，西林鹤屡招。","终当谢时去，与子住山椒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2b8602c2-0ace-4c49-a762-6de52f3353a0","tags":[]},{"id":"poem-7629ff7be2e8c6cd0181ef50","title":"少年游·佳人巧笑值千金","author":"柳永","dynasty":"宋","verses":["佳人巧笑值千金。","当日偶情深。","几回饮散，灯残香暖，好事尽鸳衾。","如今万水千山阻，魂杳杳、信沈沈。","孤棹烟波，小楼风月，两处一般心。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-155","tags":[]},{"id":"poem-762cb93ef0bab55f145f9ef9","title":"李鄠县丈人胡马行","author":"杜甫","dynasty":"唐","verses":["丈人骏马名胡骝，前年避胡过金牛。","回鞭却走见天子，朝饮汉水暮灵州。","自矜胡骝奇绝代，乘出千人万人爱。","一闻说尽急难材，转益愁向驽骀辈。","头上锐耳批秋竹，脚下高蹄削寒玉。","始知神龙别有种，不比俗马空多肉。","洛阳大道时再清，累日喜得俱东行。","凤臆龙鬐未易识，侧身注目长风生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-48568d08-d789-4eca-b9a8-5dcf09d6a516","tags":[]},{"id":"poem-762d2d5e29217c04f56a7f03","title":"郊庙歌辞 祭汾阴乐章 顺和","author":"林钟宫","dynasty":"唐","verses":["大乐和畅，殷荐明神。","一降通感，八变必臻。","有求斯应，无德不亲。","降灵醉止，休征万人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-1ad5a5b5-d7d7-4678-a728-02e11204bc29","tags":[]},{"id":"poem-76402306e4f20012c0e966c6","title":"叙事献同州侍御三首 一","author":"赵嘏","dynasty":"唐","verses":["青云席中罗袜尘，白首江上吟诗人。","登龙不及三千士，虚度膺门二十春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-96ce99c3-5898-4e39-9a70-07345817dd88","tags":[]},{"id":"poem-76417d151610f9d6ea7a10c8","title":"老仙平沙落鴈","author":"释居简","dynasty":"宋","verses":["楚天如纸字横斜，纸阔行疎对落霞。","传得夜来沙上影，不传书信伴梅花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-77618117-8319-41fb-bbd9-b68a809f8832","tags":[]},{"id":"poem-76538d0de7f4f03f9e67710c","title":"秋风函谷应诏","author":"徐贤妃","dynasty":"唐","verses":["秋风起函谷，劲气动河山。","偃松千岭上，杂雨二陵间。","低云愁广隰，落日惨重关。","此时飘紫气，应验真人还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a891f80d-fe12-429e-a820-3890a3c6af9e","tags":[]},{"id":"poem-7653fafd43fe8470f499d71a","title":"追赋画江潭苑四首 二","author":"李贺","dynasty":"唐","verses":["宝袜菊衣单，蕉花密露寒。","水光兰泽叶，带重剪刀钱。","角暖盘弓易，靴长上马难。","泪痕沾寝帐，匀粉照金鞍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b2df42a4-a3a4-4405-844c-de1bf5f05cb3","tags":[]},{"id":"poem-765eb5b0298ba03bd8a21c01","title":"题子正观察溪风亭二首  其二","author":"綦崇礼","dynasty":"宋","verses":["溪上微波起谷纹，凉飔不断快余醺。","飘飘弄袖疑轻举，馥馥吹花得细闻。","但羡园林今地主，焉知弓剑旧将军。","功名兴尽从吾好，白首安闲少似君。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a18cf985-35b8-489a-bd6b-9de74eebbbe3","tags":[]},{"id":"poem-76641295b5a6a9caf50155ae","title":"幸秦川上梓潼山","author":"后主衍","dynasty":"唐","verses":["乔岩簇冷烟，幽径上寒天。","下瞰峨眉岭，上窥华岳巅。","驱驰非取乐，按幸为忧边。","此去如登陟，歌楼路几千。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e66421b4-5322-4aa9-a64c-1bf8707decb7","tags":[]},{"id":"poem-766437ccb6092025ee712be7","title":"卜算子·五日","author":"纳兰性德","dynasty":"清","verses":["村静午鸡啼，绿暗新阴覆。","一展轻帘出画墙，道是端阳酒。","早晚夕阳蝉，又噪长堤柳。","青鬓长青自古谁，弹指黄花九②。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-85","tags":[]},{"id":"poem-7664c7a204986054251dc146","title":"和张少监晚菊","author":"徐铉","dynasty":"宋","verses":["忆共庭兰倚砌栽，柔条轻吹独依隈。","自知佳节终堪赏，为惜流光未忍开。","采撷也须盈掌握，馨香还解满罇罍。","今朝旬假犹无事，更好登临泛一杯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-10d5b39d-05c9-4599-a5d6-4f01291bae8a","tags":[]},{"id":"poem-76652093d30d093463373ba7","title":"江城子·髻鬟狼藉黛眉长","author":"韦庄","dynasty":"五代","verses":["髻鬟狼藉黛眉长，出兰房，别檀郎。","角声呜咽，星斗渐微茫。","露冷月残人未起，留不住，泪千行。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-3","tags":[]},{"id":"poem-766a570b626549ee947ec425","title":"尹令","author":"无名氏《张协状元》","dynasty":"元","verses":["它命又合孤令，奴家又合孤令。","方得二月安静，教奴又成愁闷。","(末净)闻伊丈夫，今直欲到帝京。","(末)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2568","tags":[]},{"id":"poem-766ee64ac7032d4e0b65ebc3","title":"劝人 四","author":"义存","dynasty":"唐","verses":["低头不见地，仰面不见天。","欲知白牛处（《林间录》作「欲识金刚体」），但看髑髅前。","（《林间录》卷上云此篇为见亡僧后作。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0c203e3e-0b92-4139-b3d1-21d73733ff21","tags":[]},{"id":"poem-7675b08422cd5aab50bf128e","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(末)我献灯，灯光亮，作善须降祥。","阴空保佑，保佑福无量。","愿我哥嫂身位安康。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8848","tags":[]},{"id":"poem-7677baffa6af3aaba6fccb2b","title":"·","author":"王审知","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0a5588d5-47c9-42f8-9d3d-7208c52328e4","tags":[]},{"id":"poem-76802fa71c145f09d0b7c3f8","title":"观裴秀才松石障歌","author":"皎然","dynasty":"唐","verses":["谁工此松唯拂墨，巧思丹青营不得。","初写松梢风正生，此中势与真松争。","高柯细叶动飒飒，乍听幽飗如有声。","左右双松更奇绝，龙鳞麈尾仍半折。","经春寒色聚不散，逼座阴阴将下雪。","荆门石状凌玙璠，蹙成数片倚松根。","何年蒨蒨苔黏迹，几夜潺潺水击痕。","裴生诗家后来客，为我开图玩松石。","对之自有高世心，何事劳君上山屐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-53c20649-82fb-4e0b-94b1-0b1e9425b7b8","tags":[]},{"id":"poem-7680466957fdfe996848cbaf","title":"题智门寺寄住山伊岩玉老  其一","author":"宋伯仁","dynasty":"宋","verses":["紫微深处著招提，古迹名臣事两奇。","宣子画由高庙治，越王心有孝宗知。","万竿玉立春来早，六角池深月上迟。","禅定十年帘不卷，不知门外几盘棋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ccc96586-9634-4f33-ae52-37b3f382be6f","tags":[]},{"id":"poem-76891162196d5b10e77dc833","title":"出其东门","author":"佚名","dynasty":"先秦","verses":["出其东门，有女如云。虽则如云。匪我思存。缟衣綦巾，聊乐我员。","出其𬮱阇，有女如荼。虽则如荼，匪我思且。缟衣茹藘，聊可与娱。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-92","tags":[]},{"id":"poem-768d36c6da05fc2f9d2d00a0","title":"送僧归天台寺","author":"贯休","dynasty":"唐","verses":["天台四绝寺，归去见师真。","莫折枸杞叶，令他十得嗔。","天空闻圣磬，瀑细落花巾。","必若云中老，他时得有邻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c047d8a4-35fa-4b1d-9244-4e32dd842048","tags":[]},{"id":"poem-76988e71abaaf60c6337e154","title":"春秋战国门 庄公","author":"周昙","dynasty":"唐","verses":["齐甲强临力有余，鲁庄为战念区区。","鱼丽三鼓微曹刿，肉食安能暇远谟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e0bee03c-c04b-4c8f-9725-cf433a04a23f","tags":[]},{"id":"poem-76a18472b1223439105b04dd","title":"和裴司空酬满城杨少尹","author":"张籍","dynasty":"唐","verses":["圣朝偏重大司空，人咏元和第一功。","拥节高临汉水上，题诗远入舜城中。","共惊向老多年别，更忆登科旧日同。","谁不望归丞相府，江边杨柳又秋风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-68080293-b18f-4260-9564-f5b35c06ad3a","tags":[]},{"id":"poem-76a23b5c196dfb29af06c82d","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(众)将军号令如金石，星夜便前去。","时刻莫迟延，违令怎饶你？(合)愿听钧旨便驱驰，携取宝刀回，成功最为易。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8955","tags":[]},{"id":"poem-76b36aa7e6c5fad1338cfc10","title":"经旷禅师院","author":"贯休","dynasty":"唐","verses":["吾师楞伽山中人，气岸古淡僧麒麟。","曹溪老兄一与语，金玉声利。","泥弃唾委，兀兀如顽云。","骊珠兮固难价其价，灵芝兮何以根其根。","真貌枯槁言朴略，衲衣烂黑烧岳痕。","忆昔十四五年前苦寒节，礼师问师楞伽月。","此时师握玉麈尾，报我却云非日月。","一敲粉碎狂性歇，庭松无韵冷撼骨。","搔窗擦簷数枝雪，迩来流浪于吴越。","一片闲云空皎洁，再来寻师已蝉蜕。","薝卜枝枯醴泉竭，水檀香火遗影在。","甘露松枝月中折，宝师往日真隐心，今日不能堕双血。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-67eda351-739f-4349-aef7-3793896a3c4e","tags":[]},{"id":"poem-76d15003ad2bafda16aff129","title":"河渎神·铜鼓赛神来","author":"温庭筠","dynasty":"唐","verses":["铜鼓赛神来，满庭幡盖徘徊。","水村江浦过风雷，楚山如画烟开。","离别橹声空萧索，玉容惆怅妆薄。","青麦燕飞落落，卷帘愁对珠阁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-46","tags":[]},{"id":"poem-76e059b0886aa61d309f65a7","title":"新楼诗二十首 北楼樱桃花","author":"李绅","dynasty":"唐","verses":["开花占得春光早，雪缀云装万萼轻。","凝艳拆时初照日，落英频处乍闻莺。","舞空柔弱看无力，带月葱茏似有情。","多事东风入闺闼，尽飘芳思委江城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-73a9ca7a-8cd7-4b4f-a185-23fbc95861cc","tags":[]},{"id":"poem-76e0ffe146186ea57e8b6e2c","title":"夏日南亭怀辛大","author":"孟浩然","dynasty":"唐","verses":["山光忽西落，池月渐东上。","散发乘夕凉，开轩卧闲敞。","荷风送香气，竹露滴清响。","欲取鸣琴弹，恨无知音赏。","感此怀故人，中宵劳梦想。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f8afed4e-e8cd-467f-afae-51dc149921f7","tags":["唐诗三百首","五言古诗","友情","夏天","怀人"]},{"id":"poem-76e31122cc11d116a563c418","title":"送李监岳二首  其一","author":"陈造","dynasty":"宋","verses":["李侯西州英，早著武士冠。","朅来淮上郡，鸡群见翠鸾。","清诗万卷余，脱手走铜丸。","初听耳目醒，再读毛骨寒。","解榻一瓯茗，敢作粗官看。","今者连日语，衮衮为发难。","中年可堪别，别君倍悲酸。","书来有新句，政用驱愁端。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f3f1659b-2831-4478-a137-37b4e1378798","tags":[]},{"id":"poem-76f1ce7eadc5b1b64e6af4a3","title":"腊月","author":"赵崇嶓","dynasty":"宋","verses":["腊月二十五，人家祓旧年。","山人无可祷，睡著不知天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-5f0c6310-ac82-4b37-82e8-123a3eef1ae9","tags":[]},{"id":"poem-770cf4cfcf90db2b06a789aa","title":"折杨柳","author":"李端","dynasty":"唐","verses":["东城攀柳叶，柳叶低着草。","少壮莫轻年，轻年有衰老。","柳发遍川冈，登高堪断肠。","雨烟轻漠漠，何树近君乡。","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株荣。","日暮偏愁望，春山有鸟声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-61194804-f2d2-41bc-a43e-a774f80f26dd","tags":[]},{"id":"poem-771367b762b2e884a1ae68b2","title":"与刘象正字","author":"贯休","dynasty":"唐","verses":["独居三岛上，花竹映柴关。","道广群仙惜，名成万事闲。","病多唯纵酒，静极不思山。","唯有逍遥子，时时自往还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-b89c776e-a8ff-4142-89bb-ad7eb1607de8","tags":[]},{"id":"poem-771726cb382a377efd0cde54","title":"兵要望江南 《周易》占候第二十六（三十七首） 十五","author":"易静","dynasty":"唐","verses":["占贼信，兄弟动如何。","三四爻中他（辛本、川本作「我」）尅我，逡巡来到不蹉跎，到后却安和。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7d7bd016-d91c-468b-9d82-3457da8c8cef","tags":[]},{"id":"poem-772ac7733da0cc72760735b3","title":"困中登山","author":"佚名","dynasty":"唐","verses":["戎庭闷且闲，谁复解愁颜。","步步或登岭，悠悠时往还。","野禽噪河曲，村犬吠林间。","西北望君处，踌踷日暝山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d193c4c5-ccde-4960-960e-45b3639e8c2e","tags":[]},{"id":"poem-77358a884d701ec1819aaba3","title":"循梅道中遣人如江南走笔寄诸季十首  其四","author":"李纲","dynasty":"宋","verses":["契阔三年久，惊忧一梦新。","江乡漂寓客，海峤得归人。","风雨对床夜，诗书开帐晨。","速宜寻旧约，一醉万家春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-ecaa0e35-92ab-4d3a-9d47-9af1214c054b","tags":[]},{"id":"poem-773b062c255654ef50bfa3aa","title":"江南归附后不仕述怀","author":"艾可叔","dynasty":"宋","verses":["舟在中流进退难，发虽种种此心丹。","死为元亮终书晋，生是留侯本事韩。","贫贱不忧知有道，乱离最幸是无官。","岁寒谁似东篱菊，禁得投簪日日看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c061bfdb-ba66-455b-8585-ac56954735e0","tags":[]},{"id":"poem-773d18939facb7f22af6b88a","title":"虞美人·金笼莺报天将曙","author":"李珣","dynasty":"五代","verses":["金笼莺报天将曙，惊起分飞处。","夜来潜与玉郎期，多情不觉酒醒迟，失归期。","映花避月遥相送，腻髻偏凤。","欲回娇步入香闺，倚屏无语捻云篦，翠眉低。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-47","tags":[]},{"id":"poem-774722d85cfa5528c7c58f13","title":"郊庙歌辞 享太庙乐章 严和","author":"不详","dynasty":"唐","verses":["肃肃清庙，赫赫玄猷。","功高万古，化奄十洲。","中兴丕业，上荷天休。","祗奉先构，礼备怀柔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7da09dfe-a023-474e-a933-14a6cf6ed39c","tags":[]},{"id":"poem-774b5b53cca0c514d0b270ea","title":"满江红·月上西窗","author":"晁补之","dynasty":"宋","verses":["月上西窗，书帏静、灯明又减。","水漏涩、铜壶香炉，夜霜如雪。","睡眼不曾通夕闭，梦魂争得连宵接。","念碧云、川路古来长，无由越。","鸾钗重，青丝滑。","罗带缓，小腰怯。","伊多感那更，恨离伤别。","正是少年佳意气，渐当故里春时节。","归去来、莫教子规啼，芳菲歇。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-265","tags":[]},{"id":"poem-775d524975324247a2b866f7","title":"西江月·泛泛春船载乐","author":"张先","dynasty":"宋","verses":["泛泛春船载乐，溶溶湖水平桥。","高鬟照影翠烟摇。","白纻一声云杪。","倦醉天然玉软，弄妆人惜花娇。","风情遗恨几时消。","不见卢郎年少。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-284","tags":[]},{"id":"poem-77719d9fbd08e8254534e1d8","title":"路傍树","author":"马戴","dynasty":"唐","verses":["古树何人种，清阴减昔时。","莓苔根半露，风雨节偏危。","虫蠹心将穴，蝉催叶向衰。","樵童不须翦，聊起邵公思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ba671863-b442-47ef-9a31-acb4ade9b978","tags":[]},{"id":"poem-777377079fd26f9b49eac1ff","title":"游仙窟诗 游后园","author":"崔十娘","dynasty":"唐","verses":["梅蹊命道士，桃涧伫神仙。","旧鱼成大劒，新龟类小钱。","水湄唯见柳，池曲且生莲。","欲知赏心处，桃花落眼前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0e45ea9d-3d99-415f-9682-b707f616f239","tags":[]},{"id":"poem-7778e85cb587212d909b7a7b","title":"越江吟·神仙神仙瑶池宴","author":"苏易简","dynasty":"宋","verses":["神仙神仙瑶池宴。","片片。","碧桃零落春风晚。","翠云开处，隐隐金舆挽。","玉麟背冷清风远。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-4","tags":[]},{"id":"poem-777c86e40ea7644c9910e85d","title":"梅花二首  其一","author":"林宪","dynasty":"宋","verses":["凌晨汲山泉，盥洗甫云暇。","徐行修竹间，小立疏梅罅。","尖风耿薄日，色影寒相射。","幽香定有无，纹禽踏花卸。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-5d28efec-1099-4793-a2ff-13381841fe32","tags":[]},{"id":"poem-777f9df5e61bcade1cb809a3","title":"兵后余不亭重送卢孟明游江西","author":"皎然","dynasty":"唐","verses":["携手曾此分，怳如隔胡越。","伦侯古封邑，荣盛风雨歇。","饥鼯号空亭，野草生故辙。","如何此路岐，更作千年别。","冯轼望远道，春山无断绝。","朝行入郢树，夜泊依楚月。","佳士持操高，扬才日昭晰。","离言何所赠，盈满有亏缺。","时节伤蟪蛄，芳菲忌𫛸鴂。","予思鹿门隐，心迹贵冥灭。","颓颜反芝术，昔貌成冰雪。","岁晏期尔来，销声坐岩穴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2d3ba142-1e93-4213-8400-17d45daff7f7","tags":[]},{"id":"poem-778389c5f678054333049692","title":"河渎神·孤庙对寒潮","author":"温庭筠","dynasty":"唐","verses":["孤庙对寒潮，西陵风雨萧萧。","谢娘惆怅倚兰桡，泪流玉箸千条。","暮天愁听思归乐，早梅香满山郭。","回首两情萧索，离魂何处飘泊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-45","tags":[]},{"id":"poem-7783b9f9ff620990c50c40f6","title":"题子正观察溪风亭二首  其一","author":"綦崇礼","dynasty":"宋","verses":["巧据东西面势雄，兹亭壮观一园中。","淙淙鸣窦过流水，拂拂虚簷来远风。","好解尘缨濯清泚，聊披醉衽望穹窿。","泠然便欲乘风去，汗漫相期孰与同。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-401193bb-46d2-45e2-845a-239cf67e1ab5","tags":[]},{"id":"poem-7784d134907b09448ad2b5b9","title":"别黄吟隠","author":"王镃","dynasty":"宋","verses":["饮干分别酒，话久未移舟。","潮水催行客，海山生远愁。","蝉声秋岸树，雁影夕阳楼。","今夜相思梦，芦花第几洲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-148ac550-d6d1-4c21-acfe-3246363d3898","tags":[]},{"id":"poem-77871b22518b6edbce862489","title":"春秋战国门 叔向","author":"周昙","dynasty":"唐","verses":["重禄存家不敢言，小臣忧祸亦如然。","明开谏诤能无罪，秪此宜为理国先。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8446179b-cbd6-475d-baa2-1303e06ec5b5","tags":[]},{"id":"poem-7788db9dd8e7b782bfbc767e","title":"琼花","author":"宋伯仁","dynasty":"宋","verses":["莫讶重栽聚八仙，几经边警亦堪怜。","珠帘十里春狼籍，且把天香作旧年。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-eb91c93d-6c85-40ac-833c-6dab0b01e8ed","tags":[]},{"id":"poem-779de171c0bf915d8a7eb4b2","title":"诉衷情·小园过午","author":"晁补之","dynasty":"宋","verses":["小园过午，便觉凉生翠柏。","戎葵闲出墙红，萱草静依径绿。","还是去年，浮瓜沈李，追凉故绕池边竹。","小筵促。","忽忆杨梅正熟。","下山南畔，画舸笙歌逐。","愁凝目。","使君彩笔，佳人锦字，断弦怎续。","尽日栏干曲。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-143","tags":[]},{"id":"poem-77a80a5b506353a057b7497c","title":"送裴五归京口","author":"李嘉祐","dynasty":"唐","verses":["君罢江西日，家贫为一官。","还归五陵去，只向远峰看。","暮色催人别，秋风待雨寒。","遥知到三径，唯有菊花残。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5fc627fa-6569-4d61-9498-2b3b770ae02c","tags":[]},{"id":"poem-77ad9fa8ed807e5ca9f63799","title":"题县厅壁","author":"贺德英","dynasty":"宋","verses":["昆明池里跃金鳞，怒目扬鬐不露身。","想是龙门曾点额，至今羞见钓鼇人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-75384248-36cc-4a9e-9cbd-8aa20973dd19","tags":[]},{"id":"poem-77b44ba246f313ed8eca2b29","title":"梦江南·千万恨","author":"温庭筠","dynasty":"唐","verses":["千万恨，恨极在天涯。","山月不知心里事，水风空落眼前花，摇曳碧云斜。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-6","tags":[]},{"id":"poem-77b46f3d46997514d2ea912e","title":"浣溪沙·轻打银筝坠燕泥","author":"孙光宪","dynasty":"五代","verses":["轻打银筝坠燕泥，断丝高罥画楼西，花冠闲上午墙啼。","粉箨半开新竹径，红苞尽落旧桃蹊，不堪终日闭深闺。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-44","tags":[]},{"id":"poem-77c563ea97ad8636574ccdc0","title":"凭周况先辈于朝贤乞茶","author":"孟郊","dynasty":"唐","verses":["道意勿乏味，心绪病无悰。","蒙茗玉花尽，越瓯荷叶空。","锦水有鲜色，蜀山饶芳藂。","云根才翦绿，印缝已霏红。","曾向贵人得，最将诗叟同。","幸为乞寄来，救此病劣躬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-95c9711d-cc5d-46f6-9d05-f0e27cd337b5","tags":[]},{"id":"poem-77c7b5e3da224a70b0adeb03","title":"山鹊","author":"司空图","dynasty":"唐","verses":["多惊本为好毛衣，只赖人怜始却归。","众鸟自知颜色减，妬他偏向眼前飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-7b8b9f5e-95de-44e7-8659-e4f60090292a","tags":[]},{"id":"poem-77cddf7c5cffd5bafc2a5e21","title":"白鹤禅寺","author":"王十朋","dynasty":"宋","verses":["闲上箫台顶，山深喜路通。","人家烟色里，古寺水声中。","金溅星犹在，丹成灶已空。","神仙何处觅，千载想遗风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c002e3fa-4ac3-4750-a6e6-e9a43a7c6ab6","tags":[]},{"id":"poem-77ce6fe73cb06c15ed6245cc","title":"洞仙歌令・洞仙歌·情知须病","author":"欧阳修","dynasty":"宋","verses":["情知须病，奈自家先肯。","天甚教伊恁端正。","忆年时、兰棹独倚春风，相怜处、月影花光相映。","别来凭谁诉，空寄香笺，拟问前欢甚时更。","后约与新期，易失难寻，空肠断、损风流心性。","除只把、芳尊强开颜，奈酒到愁肠，醉了还醒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-789","tags":[]},{"id":"poem-77db40e81a4ffda0e159e919","title":"酬相公再游云门寺","author":"徐凝","dynasty":"唐","verses":["远羡五云路，逶迤千骑回。","遗簪唯一去，贵赏不重来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-bfe1a801-5a11-4b7c-91b8-35fef6586d6a","tags":[]},{"id":"poem-77dcbdeffb8e314c54c843ad","title":"临江仙·遍地残花庭院静","author":"杜安世","dynasty":"宋","verses":["遍地残花庭院静，流莺对对相过。","万条风柳间婆娑。","樱桃初弄色，萱草自成窠。","早是芳菲时节晚，追游期会无多。","眉山敛翠近秋波。","日长初睡起，愁与病相和。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-929","tags":[]},{"id":"poem-77dfdb563a417ca93b9261c2","title":"赠项斯","author":"张籍","dynasty":"唐","verses":["端坐吟诗忘忍饥，万人中觅似君稀。","门连野水风长到，驴放秋原夜不归。","日煖剩收新落叶，天寒更著旧生衣。","曲江亭上频频见，为爱鸬鹚雨里飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a1adfc21-9991-486e-a47a-457753a32af5","tags":[]},{"id":"poem-77e0405112e1ec9db536c85e","title":"扬州送伯龄过江","author":"卢仝","dynasty":"唐","verses":["伯龄不厌山，山不养伯龄。","松颠有樵堕，石上无禾生。","不忍六尺躯，遂作东南行。","诸侯尽食肉，壮气吞八纮。","不唧溜钝汉，何由通姓名。","夷齐饿死日，武王称圣明。","节义士枉死，何异鸿毛轻。","努力事干谒，我心终不平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f658ef82-ee49-4fc2-b63f-81fe26a6bc06","tags":[]},{"id":"poem-77e49d599e66db831db49ae4","title":"赋月","author":"李绅","dynasty":"唐","verses":["月，光辉，皎洁。","耀乾坤，静空阔。","圆满中秋，玩争诗哲。","玉兔镝难穿，桂枝人共折。","万象照乃无私，琼台岂遮君谒。","抱琴对弹别鹤声，不得知音声不切。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5ca211d7-18e4-41d4-a754-c72c28e846d6","tags":[]},{"id":"poem-77eaee803d7398c83d5e2038","title":"张左丞挽歌二首 二","author":"李端","dynasty":"唐","verses":["祸集钩方失，灾生劒忽飞。","无由就日拜，空忆自天归。","门吏看还葬，宫官识赐衣。","东堂哀赠毕，从此故臣稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2eb64614-d5a4-43a5-a796-a485efaeaced","tags":[]},{"id":"poem-77ec4e5afe8281dbe9bfaaef","title":"杨柳枝·有池有榭即蒙蒙","author":"孙光宪","dynasty":"五代","verses":["有池有榭即蒙蒙，浸润翻成长养功。","恰似有人长点检，着行排立向春风。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-42","tags":[]},{"id":"poem-77ed345241f78afe79ba2c2d","title":"墨竹","author":"释居简","dynasty":"宋","verses":["搜搅微茫到物初，解衣盘礴便扶疎。","岁寒节节曾参透，不负刚明一寸虚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3d7691b1-0de8-4b7a-867b-855b5c4f9370","tags":[]},{"id":"poem-77fa85c85f2f6cc2b70276c9","title":"游四门","author":"杨景贤","dynasty":"元","verses":["除俺做洪州知府教风俗，(刘云)小人正是本处人。","(夫人唱)你正是本乡居。","着殷勤相公亲抬举，免税脱丁夫。","咱两口，都不会说嚣虚。","(刘云)多谢夫人。","禀老爷，好顺风，请早些下船罢。","(陈同夫人下船，分付开船科)(刘云)不免扯起篷来。","(夫人唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7943","tags":[]},{"id":"poem-7801840295005d58916d3af9","title":"终南","author":"佚名","dynasty":"先秦","verses":["终南何有？有条有梅。君子至止，锦衣狐裘。颜如渥丹，其君也哉！","终南何有？有纪有堂。君子至止，黻衣绣裳。佩玉将将，寿考不忘！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-129","tags":[]},{"id":"poem-78026488456d20a3e532b76b","title":"宿青草渡","author":"王镃","dynasty":"宋","verses":["夜深犹有去来船，长江倒影涵青天。","鹤寒梦觉松梢月，流水残梅浸香雪。","山翁呼儿沽酒归，独客有感未睡时。","提剑起舞摇斗宿，醉里天风生两袖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-379e7065-23f1-40c0-91b2-bee92630c5f1","tags":["长江"]},{"id":"poem-7803545d6e2302e4d2bd1343","title":"句  其二","author":"滕元发","dynasty":"宋","verses":["寒日边声断，春风塞草长。","传闻汉都护，归奉万年觞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d5d87de9-b2a6-419c-804c-f8eee64a4d84","tags":[]},{"id":"poem-780aeac3fa734725865ee703","title":"郊庙歌辞 祭神州乐章 送神","author":"不详","dynasty":"唐","verses":["神州阴祀，洪恩广济。","草树沾和，飞沈沐惠。","礼修鼎俎，奠歆瑶币。","送乐有章，灵轩其逝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d70c3690-62ad-4004-b45e-6bb39c53f844","tags":[]},{"id":"poem-78136a27109d149d4df41917","title":"烈祖挽辞（题拟） 二","author":"宋齐丘","dynasty":"唐","verses":["宫衣无组绣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-eb67b39a-4717-4d8d-836a-86354d87ddaa","tags":[]},{"id":"poem-781acb62c1032015648cd011","title":"苏氏别业","author":"祖咏","dynasty":"唐","verses":["别业居幽处，到来生隐心。","南山当户牖，澧水映园林。","竹覆经冬雪，庭昏未夕阴。","寥寥人境外，闲坐听春禽。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-蘇氏別業","tags":[]},{"id":"poem-781e271a1a401f8265173c82","title":"又一首","author":"张𬸦","dynasty":"唐","verses":["未必由诗得，将诗故表怜。","闻渠掷入火，定是欲相然。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5e09e26f-7b2b-4731-94a6-d41f9403b3f2","tags":[]},{"id":"poem-783f8199271040e8f4be8268","title":"登咸阳北寺楼","author":"张籍","dynasty":"唐","verses":["高秋原上寺，下马一登临。","渭水西来直，秦山南向深。","旧宫人不住，荒碣路难寻。","日暮凉风起，萧条多远心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9cf0aafb-1902-4f56-8c86-1a92ee61158c","tags":[]},{"id":"poem-7840155a2a2a5189f0c9706b","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆题惠山寺书堂","author":"李绅","dynasty":"唐","verses":["故山一别光阴改，秋露清风岁月多。","松下壮心年少去，池边衰影老人过。","白云生灭依岩岫，青桂荣枯托薜萝。","惟有此身长是客，又驱旌斾寄烟波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e951ac7e-488c-4282-a368-a58852fc9f2f","tags":[]},{"id":"poem-7849b09ede43d05d81f68c71","title":"送沈太博倅滑台","author":"苏颂","dynasty":"宋","verses":["早岁淮阳宰邑初，相君连上荐能书。","新从墨绶诸侯国，便领油泥别驾舆。","东郡提封今辅屏，南都接轸旧乡闾。","优游乐职人应羡，官便家荣两莫如。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a9b0d561-c04e-4540-8e8c-05b178fb1bb8","tags":[]},{"id":"poem-7849fc354dc449f02995c9bb","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["不得商于又失齐，楚怀方寸一何迷。","明知秦是虎狼国，更忍车轮独向西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-25e584a2-98bd-413c-b3c8-6b661b942867","tags":[]},{"id":"poem-784e8f820a623c1d171e94a8","title":"瓠叶","author":"佚名","dynasty":"先秦","verses":["幡幡瓠叶，采之亨之。君子有酒，酌言尝之。","有兔斯首，炮之燔之。君子有酒，酌言献之。","有兔斯首，燔之炙之。君子有酒，酌言酢之。","有兔斯首，燔之炮之。君子有酒，酌言酬之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-230","tags":[]},{"id":"poem-78549b59f841af687377a2a0","title":"和择之看雪","author":"张栻","dynasty":"宋","verses":["岳背三冬雪，真同不夜城。","野云何晃荡，涧水助空明。","行橐多新句，青山有旧盟。","堂堂身世事，渠谩说三生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-92a4778b-c370-4119-8d0b-6b3e1e166496","tags":[]},{"id":"poem-785ce450bb8465550355d774","title":"春宫怨","author":"周朴","dynasty":"唐","verses":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1d6885a4-d11e-4428-80a8-fcf75d7a41aa","tags":["唐诗三百首","宫怨","春天","写景","女子","五言律诗"]},{"id":"poem-786e965816fee0230425a466","title":"又","author":"释了惠","dynasty":"宋","verses":["玉腕指尖新，力能提万钧。","上他篮子里，未必是金鳞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-36d95684-4f64-44e0-8841-0eeefc1fef95","tags":[]},{"id":"poem-78814edb84349fe46e624a4e","title":"和翁士秀瑞香水仙二首  其二","author":"曾协","dynasty":"宋","verses":["正白深黄态自浓，不将红粉作华容。","却疑洛浦波心见，合向瑶台月下逢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1315a0e2-4259-4b9c-a2c3-d60302b11d29","tags":[]},{"id":"poem-78833fb6db784bc506268f2f","title":"绿水词","author":"李贺","dynasty":"唐","verses":["今宵好风月，阿侯在何处。","为有倾人色，翻成足愁苦。","东湖采莲叶，南湖拔蒲根。","未持寄小姑，且持感愁魂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-54fb0ffc-a287-41a6-b415-ebf47436548a","tags":["爱情","回忆","女子","相思"]},{"id":"poem-789c895337d285f78c3b12ac","title":"仙思  其一","author":"赵崇鉘","dynasty":"宋","verses":["水殿风清急景斜，灵君初下五云车。","碧罗宝扇双题字，记是谁人咏落花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-6e24e46b-824c-42ba-9ce2-dcac597d59ea","tags":[]},{"id":"poem-78a2fdb5268e01f7f2104be5","title":"偈十六首  其七","author":"释士珪","dynasty":"宋","verses":["一阳生，万物萌。","天本清，地常宁。","四时行，万汇成。","如纬经，如权衡。","天心平，人心诚。","日月明，鬼神警。","方知天地分浊清，古今无亏盈。","圣泉拄杖犹通灵，敲骨出髓。","方悟从上诸圣碗鸣声，犹较芭蕉半月程。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-59cdc58f-a4ef-49aa-b422-87d51ccc981f","tags":[]},{"id":"poem-78a43f189576e535237fd53d","title":"发秦州","author":"杜甫","dynasty":"唐","verses":["我衰更嬾拙，生事不自谋。","无食问乐土，无衣思南州。","汉源十月交，天气凉如秋。","草木未黄落，况闻山水幽。","栗亭名更佳，下有良田畴。","充肠多薯蓣，崖蜜亦易求。","密竹复冬笋，清池可方舟。","虽伤旅寓远，庶遂平生游。","此邦俯要冲，实恐人事稠。","应接非本性，登临未销忧。","谿谷无异石，塞田始微收。","岂复慰老夫，惘然难久留。","日色隐孤戍，乌啼满城头。","中宵驱车去，饮马寒塘流。","磊落星月高，苍茫云雾浮。","大哉乾坤内，吾道长悠悠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5aee80a3-db54-4787-9e2a-491e108b8f1d","tags":[]},{"id":"poem-78a4e7994566181da6965cde","title":"宿疏山戏成一绝","author":"李纲","dynasty":"宋","verses":["疏山缘熟岂无由，暂到人人识故侯。","临别慇勤语禅子，秪来托宿不来游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8e7b4d19-e5bb-41ea-a0a4-30cefbd1a338","tags":[]},{"id":"poem-78a5a6123d4d7818580d05ce","title":"和暑夜偶作之什","author":"李昉","dynasty":"宋","verses":["新搆华居近禁城，旋栽松桧满中庭。","顺风子细闻清漏，隔竹依稀见落星。","万乘异恩无路报，千年昌运此时丁。","一轩明月谁为伴，应共金昆醉复醒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-bcf948f9-02de-41c9-a220-c68e1e2aa51e","tags":[]},{"id":"poem-78a6716ec414e472165342f3","title":"更漏子·听寒更","author":"孙光宪","dynasty":"五代","verses":["听寒更，闻远雁，半夜萧娘深院。","扃绣户，下珠帘，满庭喷玉蟾。","人语静，香闺冷，红幕半垂清影。","云雨态，蕙兰心，此情江海深。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-21","tags":[]},{"id":"poem-78a86198997225870ecd3355","title":"阮郎归·湘天风雨破寒初","author":"秦观","dynasty":"宋","verses":["湘天风雨破寒初。","深沈庭院虚。","丽谯吹罢《小单于》。","迢迢清夜徂。","乡梦断，旅魂孤。","峥嵘岁又除。","衡阳犹有雁传书。","郴阳和雁无。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-69","tags":["宋词三百首"]},{"id":"poem-78a9a72145730bdd655871f0","title":"春草池","author":"张又新","dynasty":"唐","verses":["谢公梦草一差微，谪宦当时道不机。","且谓飞霞游赏地，池塘烟柳亦依依。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b95f7661-648c-42f9-b588-d1031babdc19","tags":[]},{"id":"poem-78af6a39303514b13b468d8b","title":"山居诗  其五七","author":"释延寿","dynasty":"宋","verses":["一生占断白云乡，适意孤高志自强。","报晓音声栖鸟语，漏春消息早梅香。","吟经徐傍芙蕖岸，得偈闲书薜荔墙。","大道最亲无达者，苦携瓶锡叩禅堂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4bd2ca53-c71d-45e0-aaf6-41d5a4a13d55","tags":[]},{"id":"poem-78b667cf3af7ddea3dbbf461","title":"锦堂月","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［旦］华发斑斑，韶光荏苒，双亲幸喜平安。","庆此良辰，人人对景欢颜。","画堂中宝篆香销，玉盏内流霞光泛。","［合］齐祝赞，愿福如东海，寿比南山。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8030","tags":[]},{"id":"poem-78b676cd62a4d170d9a5ded2","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［丑上］富家郎央我为媒，要娶我侄女为妻。","说开说合，非同容易，也全凭虚心冷气。","匹配，端的是老娘为最。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8071","tags":[]},{"id":"poem-78b69fe934356bb4ec26616c","title":"西江晚泊","author":"赵嘏","dynasty":"唐","verses":["茫茫霭霭失西东，柳浦桑村处处同。","戍鼓一声帆影尽，水禽飞起夕阳中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-0b7225ba-73e3-49ee-be99-6725380a2edb","tags":[]},{"id":"poem-78c5cb63cadba808d39ed610","title":"到家","author":"赵嘏","dynasty":"唐","verses":["童稚苦相问，归来何太迟。","共谁争岁月，赢得鬓边丝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e37422f9-a0eb-4593-8b8b-cde70dd03dcd","tags":[]},{"id":"poem-78c97062dae77d8d1e7a1296","title":"雪中送青州薛评事","author":"马戴","dynasty":"唐","verses":["腊景不可犯，从戎难自由。","怜君急王事，走马赴边州。","岳雪明日观，海云冒营丘。","慙无斗酒泻，敢望御重裘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5dc28968-a609-46bf-ac05-885400bcebe7","tags":[]},{"id":"poem-78cadfcabbef700f88d0e20d","title":"御街行·燔柴烟断星河曙","author":"柳永","dynasty":"宋","verses":["燔柴烟断星河曙。","宝辇回天步。","端门羽卫簇雕阑，六乐舜韶先举。","鹤书飞下，鸡竿高耸，恩霈均寰寓。","赤霜袍烂飘香雾。","喜色成春煦。","九仪三事仰天颜，八彩旋生眉宇。","椿龄无尽，萝图有庆，常作乾坤主。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-96","tags":[]},{"id":"poem-78cb365fc1fa4aed412707e6","title":"送人自苏州之长沙县官","author":"薛能","dynasty":"唐","verses":["驱马复乘流，何时发虎丘？","全家上南岳，一尉事诸侯。","茶煮朝宗水，船停调角州。","炎方好将息，卑湿旧堪忧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1d22aca8-9cd4-4177-a871-dc56d930c714","tags":["衡山"]},{"id":"poem-78d5f0e06fa0b3b63b5a1ead","title":"同薛司直诸公秋霁曲江俯见南山作","author":"高适","dynasty":"唐","verses":["南山郁初霁，曲江湛不流。","若临瑶池前，想望昆仑丘。","廻首见黛色，眇然波上秋。","深沈俯峥嵘，清浅延阻修。","连潭万木影，插岸千岩幽。","杳霭信难测，渊沦无暗投。","片云对渔父，独鸟随虚舟。","我心寄青霞，世事慙白鸥。","得意在乘兴，忘怀非外求。","良辰自多暇，欣与数子游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-8c75cce0-2e86-4277-bef4-dd0fe6b1c1aa","tags":[]},{"id":"poem-78e35624869f2d88e7a129e2","title":"自平阳馆赴郡","author":"畅当","dynasty":"唐","verses":["晨兴平阳馆，见月沈江水。","溶溶山雾披，肃肃沙鹭起。","奉恩谬符竹，伏轼省顽鄙。","何当施教化，愧迎小郡史。","寥落火耕俗，征途青冥里。","德绥及吾民，不德将鹿矣。","擒奸非性能，多愍会衰齿。","恭承共理诏，恒惧坠诸地。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c0f6fbf7-0066-4d48-94bf-cb0c06c031a2","tags":[]},{"id":"poem-78e71936d29f3430748746cd","title":"故太子詹事王公挽诗二首  其一","author":"张栻","dynasty":"宋","verses":["大节元无玷，中心本不欺。","排奸力扛鼎，忧国鬓成丝。","方喜三旌召，俄兴一鉴悲。","西风吹泪眼，夫岂哭吾私。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-1687a762-b791-4c48-ac81-9739b290e86f","tags":[]},{"id":"poem-78fb03265b8cbfec204079fd","title":"同司空文明过坚上人故院","author":"李端","dynasty":"唐","verses":["我与雷居士，平生事远公。","无人知是旧，共到影堂中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-18e28a30-bd37-43c6-be88-a08d29b4f571","tags":[]},{"id":"poem-7908332a22b9d316f831a362","title":"秋登宣城谢眺北楼","author":"李白","dynasty":"唐","verses":["江城如画里，山晚望晴空。","两水夹明镜，双桥落彩虹。","人烟寒橘柚，秋色老梧桐。","谁念北楼上，临风怀谢公。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秋登宣城謝眺北樓","tags":[]},{"id":"poem-790d2e56e1f5923e9c80d171","title":"宿棣华馆闻雁","author":"雍裕之","dynasty":"唐","verses":["不堪旅宿棣花馆，况有离群鸿雁声。","一点秋灯残影下，不知寒梦几回惊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-24a814fd-1ab9-4929-8ef5-e04ca850144e","tags":[]},{"id":"poem-79135a7ca6090dc936c5a020","title":"送狄参军赴杭州","author":"马戴","dynasty":"唐","verses":["新官非次受，圣主宠前勋。","关雪发车晚，风涛挂席闻。","海门山叠翠，湖岸郡藏云。","执简从公后，髯参岂胜君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b765fc21-7f05-4b97-891a-25ffc37d3511","tags":[]},{"id":"poem-791a20b76bccc93c12c30b4c","title":"句","author":"陈上卿","dynasty":"唐","verses":["门前萧索青松老，云里逍遥白鹤闲。","波澜晴泛三春色，桃李争开两岸芳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e80064b6-d3e5-4d20-abe7-60c9275d929f","tags":[]},{"id":"poem-791ea2fc9ad957311f4e4596","title":"腊月雨","author":"刘东叔","dynasty":"唐","verses":["且雨且冻山径滑，是谁作此琉璃变？","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a437222a-edee-43b4-9ff9-9726bca4e2ee","tags":[]},{"id":"poem-7920fa9bff2d144b4bd92204","title":"临江仙·千顷翠围遮绿净","author":"王质","dynasty":"宋","verses":["千顷翠围遮绿净，菱花影落波中。","看看红锦漾清风。","此时催入觐，烟浪拍云空。","伫见觚棱栖宝爵，旌旗全仗飞龙。","赭黄一点现真容。","御麻宣未毕，云镜上天东。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-334","tags":[]},{"id":"poem-793629926e5f6cda647e50be","title":"送徐州张建封还镇","author":"德宗皇帝","dynasty":"唐","verses":["牧守寄所重，才贤生为时。","宣风自淮甸，授钺膺藩维。","入觐展遐恋，临轩慰来思。","忠诚在方寸，感激陈情词。","报国尔所向，恤人予是资。","欢宴不尽怀，车马当还期。","谷雨将应候，行春犹未迟。","勿以千里遥，而云无己知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-73f35093-8a40-44ba-ba98-6b4457303408","tags":[]},{"id":"poem-793646bcd3f40fadac1c4972","title":"幺","author":"杨景贤","dynasty":"元","verses":["他每点上绛蜡，铺着绣衾。","等到咱来。","斟将酒至，盼得君临。","(猪云)此间小洞中，索是定害娘子。","(裴女唱)我不曾志意缝联，殷勤妆洗，存心织纫，(猪云)人对我说，他们不服事你，待我责罚这厮们。","(裴女唱)你可也休听人恁般谗谮。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4507","tags":[]},{"id":"poem-7936e5be08273e164528f3bc","title":"村居即事","author":"范成大","dynasty":"宋","verses":["绿遍山原白满川，子规声里雨如烟。","乡村四月闲人少，才了蚕桑又插田。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-村居即事","tags":[]},{"id":"poem-7941d60d40250738c89b5780","title":"遇边使","author":"卢殷","dynasty":"唐","verses":["累年无的信，每夜梦边城。","袖掩千行泪，书封一尺情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fa7f2085-67ca-4b38-b9ec-7153f430559d","tags":[]},{"id":"poem-7945c28f9f4471661a03db16","title":"寄题明月禅院（之二）","author":"赞宁","dynasty":"唐","verses":["积翠湖心迤逦长，洞台萧寺两交光。","鸟行黑点波涛白，枫叶红莲橘柚黄。","人我绝时偎树石，是非来处接帆樯。","如何遂得追游性，摆却营营不急忙。","（见范成大纂《吴郡志》卷三十三。","）（按：《吴郡志》录赞宁诗二首，题作《寄题水月禅院》。","然同卷云：水月禅院，「天祐四年，刺史曹珪以『明月』名之，皇朝祥符间诏易今名。","」院名「水月」，在赞宁死后，克据旧名改题。","其一已收入《全唐诗补逸》卷十八。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6e87ebec-2da0-49b3-83dd-10f46d9a61cb","tags":[]},{"id":"poem-794ef6956e8945098535997f","title":"浣溪沙·五字诗中目乍成","author":"纳兰性德","dynasty":"清","verses":["五字诗中目乍成。","尽教残福折书生。","手挼裙带那时情。","别后心期和梦杳，年来憔悴与愁并。","夕阳依旧小窗明。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-50","tags":[]},{"id":"poem-7954768b8519a4b46930f3b7","title":"采桑子·冷香萦遍红桥梦","author":"纳兰性德","dynasty":"清","verses":["冷香萦遍红桥梦，梦觉城笳。","月上桃花，雨歇春寒燕子家。","箜篌别后谁能鼓，肠断天涯。","暗损韶华，一缕茶烟透碧纱。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-91","tags":[]},{"id":"poem-795b1965060557ac761fa6dc","title":"奉和二兄罢使遣马归延州","author":"李贺","dynasty":"唐","verses":["空留三尺劒，不用一丸泥。","马向沙场去，人归故国来。","笛愁翻陇水，酒喜沥春灰。","锦带休惊雁，罗衣尚鬬鸡。","还吴已渺渺，入郢莫凄凄。","自是桃李树，何畏不成蹊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-795f68f3-7560-456d-98f6-34779af12e7f","tags":[]},{"id":"poem-795caaec41ffe6b294df22e4","title":"虞美人·黄昏又听城头角","author":"纳兰性德","dynasty":"清","verses":["黄昏又听城头角，病起心情恶。","药炉初沸短檠青，无那残香半缕恼多情。","多情自古原多病，清镜怜清影。","一声弹指泪如丝，央及东风休遣玉人知。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-200","tags":[]},{"id":"poem-7965e2d3fae09099ea035f94","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["把真容再画取，如今日封赠伊。","把这眉头放展舒，只愁瘦容难做肥。","岂特奴心知感德，料他也衔恩泉世里。","(合前)(贴唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5281","tags":[]},{"id":"poem-7969f3a73dad91f554c8f39e","title":"寄上舍人叔","author":"李端","dynasty":"唐","verses":["车马朝初下，看山忆独寻。","会知逢水尽，且爱入云深。","残雨开斜日，新蝉发迥林。","阮咸虽别巷，遥识此时心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-04fb8049-647f-44a5-b729-20ba3af1399a","tags":[]},{"id":"poem-796b2935a7ac2fd000e53220","title":"定西番·苍翠浓阴满院","author":"毛熙震","dynasty":"五代","verses":["苍翠浓阴满院，莺对语，蝶交飞，戏蔷薇。","斜日倚栏风好，余香出绣衣。","未得玉郎消息，几时归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-3","tags":[]},{"id":"poem-7972d86e087580dbdfe85d60","title":"卜算子·得酒解愁烦","author":"吕渭老","dynasty":"宋","verses":["得酒解愁烦，多病还疏酒。","本是多情失意人，此味如何受。","沈醉且高歌，不饮心常有。","守著残灯斗著眉，怎不腰肢瘦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-91","tags":[]},{"id":"poem-7978825575e7a93466ffa5a5","title":"宁州春思","author":"项斯","dynasty":"唐","verses":["失意离城早，边城任见花。","初为断酒客，旧识卖书家。","寒寺稀无雪，春风亦有沙。","思归频入梦，即路不言赊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-6147f80e-6161-4a16-aa92-27210e6d856b","tags":[]},{"id":"poem-797d17b90f826ee454c03d41","title":"伤李端","author":"衞象","dynasty":"唐","verses":["才子浮生促，泉台此路赊。","官卑扬执戟，年少贾长沙。","人去门栖𫛳，灾成酒误虵。","唯余封禅草，留在茂陵家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1a10b41f-45f7-42fe-9728-30d1e9418660","tags":[]},{"id":"poem-797e9fc644f9c999cceef952","title":"时充之访盘溪有诗次韵","author":"王柏","dynasty":"宋","verses":["圣贤不出此心公，有为为之未必充。","绝学当归三洞左，正源欲障百川东。","坐春立雪谁能继，弄月吟风岂浪从。","方己乌头力应鲜，因循又过一年终。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-2cf885c5-9b5b-4cf8-baf8-67f74ec46a96","tags":[]},{"id":"poem-7996cd9f58b02ecbfa41ed8d","title":"鹧鸪天·学画宫眉细细长","author":"欧阳修","dynasty":"宋","verses":["学画宫眉细细长。","芙蓉出水斗新妆。","只知一笑能倾国，不信相看有断肠。","双黄鹄，两鸳鸯。","迢迢云水恨难忘。","早知今日长相忆，不及从初莫作双。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-768","tags":[]},{"id":"poem-799dc2353967e357409eddf4","title":"双黄鹄歌送别","author":"王维","dynasty":"唐","verses":["天路来兮双黄鹄，云上飞兮水上宿。","抚翼和鸣整羽族，不得已，忽分飞。","家在玉京朝紫微，主人临水送将归。","悲笳嘹唳垂舞衣，宾欲散兮复相依。","几往返兮极浦，尚裴回兮落晖。","岸上火兮相迎，将夜入兮边城。","鞍马归兮佳人散，怅离忧兮独含情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-179e62dd-8983-45c3-a3db-52d9bd1871af","tags":[]},{"id":"poem-79a8bf8c3e52181a0331450f","title":"哭苗员外呈张参军","author":"司空曙","dynasty":"唐","verses":["思君宁家宅，久接竹林期。","尝值偷琴处，亲闻比玉时。","高人不易合，弱冠早相知。","试艺临诸友，能文即我师。","凌寒松未老，先暮槿何衰。","季子生前别，羊昙醉后悲。","寿堂乖一恸，奠席阻长辞。","因沥殊方泪，遥成墓下诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-261d8e84-5e2f-4729-abc7-9e3c6730fa80","tags":[]},{"id":"poem-79ad3b9116c372c4a9d29deb","title":"寒夜","author":"杜小山","dynasty":"宋","verses":["寒夜客来茶当酒，竹炉汤沸火初红。","寻常一样窗前月，才有梅花便不同。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-寒夜","tags":[]},{"id":"poem-79b10388ebd82c0729e1ee04","title":"浆水令","author":"萧德祥《小孙屠》","dynasty":"元","verses":["四时中春光最美，共游赏更莫待迟。","暖风逐日好天气，莫蹉跎过了，谩自伤悲。","花深处，酒望垂，可惜解貂留佩。","同欢会。","同欢会，同欢醉归。","扶归去，扶归去，带好花枝。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8568","tags":[]},{"id":"poem-79b25bde30df56a2ee888154","title":"南歌子·一点檀心紫","author":"权无染","dynasty":"宋","verses":["一点檀心紫，千重粉翅光。","蔷薇水浸淡鹅黄。","别是一般风韵、断人肠。","有艳难欺雪，无花可此香。","寻思无计与幽芳。","除是玉人清瘦、道家妆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-868","tags":[]},{"id":"poem-79b6bb0b4823e506b48bdafc","title":"朱哥儿","author":"萧德祥《小孙屠》","dynasty":"元","verses":["哥哥听兄弟拜启：它须烟花泼妓，水性从来怎由己，缘何会做得人头妻？伊不听，兄弟劝时，也须看前人例。","(生)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8606","tags":[]},{"id":"poem-79b86578ff980ee7f7524911","title":"汲水诗","author":"华镇","dynasty":"宋","verses":["汲水苦绠短，低回就清浅。","绠短傥有续，重渊良不远。","清浅本无源，其涸易见𪾢。","重渊酌愈出，流波被沟畎。","膏肓苟愿治，会须好俞扁。","所之在万里，庸可策驽蹇。","白茅满原隰，刈之何不勉。","缉索绠乃长，单极恣舒卷。","寄声汲引者，功微利亦鲜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-5cf01bf8-e1d5-4654-a61c-119275afaf10","tags":[]},{"id":"poem-79bd6bb144ec8e787b83a513","title":"经无锡县醉后吟","author":"赵嘏","dynasty":"唐","verses":["客过无名姓，扁舟系柳阴。","穷秋南国泪，残日故乡心。","京洛衣尘在，江湖酒病深。","何须觅陶令，乘醉自横琴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5684ca6d-deb6-4095-8c06-82a92e2bd47a","tags":[]},{"id":"poem-79d23398283c13dbdbbd44ca","title":"生姜芽","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外］从他往京畿，两月余，一心指望登科第，回乡里，怎舍得轻辜负？相门重赘多娇女，不思量撇下荆钗妇。","［合］弃旧怜新小人儒，亏心折尽平生福。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8189","tags":[]},{"id":"poem-79d595eca333316049d64981","title":"泉水","author":"佚名","dynasty":"先秦","verses":["毖彼泉水，亦流于淇。有怀于卫，靡日不思。娈彼诸姬，聊与之谋。","出宿于泲，饮饯于祢。女子有行，远父母兄弟，问我诸姑，遂及伯姊。","出宿于干，饮饯于言。载脂载辖，还车言迈。遄臻于卫，不瑕有害？","我思肥泉，兹之永叹。思须与漕，我心悠悠。驾言出游，以写我忧。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-38","tags":[]},{"id":"poem-79e0c6ce73175c68077e6400","title":"冬夜非所","author":"佚名","dynasty":"唐","verses":["长夜闭荒城，更深恨转盈。","星济数道赤，月出半山明。","不闻村犬吠，空听虎狼声。","愁卧眠虽着，时时梦里惊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-73c79244-cc31-43a2-80a8-6267e8b7d69e","tags":[]},{"id":"poem-79e568b5e37f919a2d5d4f28","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["诗书礼乐曾谙历，我敢负伊！伊我放心，不须要虑及辜我妻，虑及辜负伊。","(合)愿得前意镇如初，团圆到底。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2550","tags":[]},{"id":"poem-79e572c7fbd634c9f9d569a9","title":"赴京旅次感怀","author":"常衮","dynasty":"唐","verses":["万里云烟绕画楼，客居无事转深愁。","秋风翠阁看初动，玉露金茎望欲流。","廿载承恩谁报主，一生僚属且封侯。","明朝努力长安道，不为晴川恋旧游。","（以上二诗见沁泉山馆郭柏苍校刊本《唐制诏集》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1f558ee5-d081-4656-82b3-6124886cbbdc","tags":[]},{"id":"poem-7a07b75cecac1dc34318fc69","title":"观吉王花烛","author":"徐铉","dynasty":"宋","verses":["王门嘉礼万人观，况是新承置醴欢。","花烛喧阗丞相府，星辰摇动远游冠。","歌声暂阕闻宫漏，云影初开见露盘。","帝里佳期频赋颂，长留故事在金銮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c62208ca-4719-43ab-8791-241cbf81187e","tags":[]},{"id":"poem-7a0ec345644ba8540d41d1e6","title":"明堂观礼杂咏十三首 天街夜步","author":"王同祖","dynasty":"宋","verses":["风不停云月更清，千门绣幕笑歌声。","御营巡检无拘束，走马天街夜达明。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-2c1c74e5-c10b-4262-a908-3de078af5ed0","tags":[]},{"id":"poem-7a12b77292d5043caacc995b","title":"终南山","author":"王维","dynasty":"唐","verses":["太乙近天都，连山到海隅。","白云回望合，青霭入看无。","分野中峰变，阴晴众壑殊。","欲投何处宿，隔水问樵夫。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-終南山","tags":[]},{"id":"poem-7a17688f6c993a4082f19df9","title":"送汤中丞和蕃","author":"皇甫曾","dynasty":"唐","verses":["继好中司出，天心外国知。","已传尧雨露，更说汉威仪。","陇上应回首，河源复载驰。","孤峰问徒御，空碛见旌麾。","春草乡愁起，边城旅梦移。","莫嗟行远地，此去荅恩私。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5ceea715-909e-454c-ad89-5cda63cc119d","tags":[]},{"id":"poem-7a252ab384f1edb9e9e867af","title":"望江南・忆江南·内外遍","author":"陈朴","dynasty":"宋","verses":["内外遍，八转始还元。","地带长垂生坎户，周行胎息贯天门。","太始道方存。","纯一体，黑赤气常喷。","丹火发来烧内境，冷泉深处浴猴孙。","神水赤龟吞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-967","tags":[]},{"id":"poem-7a25cb737cc4d670d24bbd08","title":"赠山翁","author":"李涛","dynasty":"宋","verses":["松萝深处住，闲野不生愁。","鸟语烟岚静，水声门户秋。","花间归洞路，山下钓鱼舟。","沐浴圣王化，自怜丝满头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0d10a855-4cdc-4064-a221-f95e554504c0","tags":[]},{"id":"poem-7a35bde8e83114be4bd95e6a","title":"驻马听","author":"杨景贤","dynasty":"元","verses":["大众虔诚，法鼓金铙出寺迎。","诸天相敬，铜钟玉磬映山鸣。","眼前罗着药师灯，心中悬托着轩辕镜。","但能勾灵光一点明，登时间跳出琉璃井。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3408","tags":[]},{"id":"poem-7a36193cb161b3b34b50661c","title":"送裴司门倅越","author":"宋敏求","dynasty":"宋","verses":["剡中新佐郡，去路触炎威。","民富杼机利，地含山水晖。","樵风送舟𬘫，梅雨润朝衣。","政在宜谣俗，当期奏课归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5193b764-96f7-4396-bdbe-5e69b838e837","tags":[]},{"id":"poem-7a440560f8fb7bba5a4546bf","title":"偈颂（幷序○序为南岳齐己撰） 四十二","author":"居遁","dynasty":"唐","verses":["昔生未了今须了，此生度取累此身。","古佛未悟同今者，悟了今人即古人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-36cbce1b-3552-4147-ba5a-0edbdece9e91","tags":["衡山"]},{"id":"poem-7a54cf2b761cd950cdb599ed","title":"寄江都路员外","author":"徐铉","dynasty":"宋","verses":["吾兄失意在东都，闻说襟怀任所如。","已纵乖慵为傲吏，有何关键制豪胥。","县斋晓闭多移病，南亩秋荒忆遂初。","知道故人相忆否，嵇康不得懒修书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c77b5693-bb2c-4918-81dd-fbb191b04ea2","tags":[]},{"id":"poem-7a56336a4a1d4ab0685388fb","title":"送客东归","author":"李端","dynasty":"唐","verses":["昨夜东风吹尽雪，两京路上梅花发。","行人相见便东西，日暮溪头饮马别。","把君衫袖望垂杨，两行泪下思故乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-12cdd629-7c39-4d78-bfcc-246cffbb7127","tags":[]},{"id":"poem-7a595a4879474890f31f23b7","title":"思园春","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)久阻尊颜想念勤。","(老旦)孩儿，此逢将谓是梦和魂。","(外)这女儿是谁？(老旦)是我途中厮认来的。","(小旦)奴是不应亲者，今日强来亲。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3030","tags":[]},{"id":"poem-7a5fae9ed0e7aa2d220f3546","title":"蝶恋花·未就丹砂须九转","author":"韩淲","dynasty":"宋","verses":["未就丹砂须九转。","谁把新词，歌绕梁尘遍。","拍拍韶华春意满。","揆予初度文何健。","恰是山花汀草远。","独乐园林，不梦笙歌殿。","灵气仙才非小见。","霞杯漫道蟠桃献。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-500","tags":[]},{"id":"poem-7a6191eb7938ddf235967b83","title":"同前换头","author":"萧德祥《小孙屠》","dynasty":"元","verses":["你却说得是，教人泪暗滴。","我当初娶它归，将谓好行止。","谁知甚的？事到头来，全无区处。","受尽凌迟，如今悔之无及。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8661","tags":[]},{"id":"poem-7a6b756efcf2932873fd8719","title":"酬燕公出湖见寄","author":"赵冬曦","dynasty":"唐","verses":["纶綍有成命，旌麾不可攀。","湘川朝目断，荆阙夕波还。","果枉东瞻唱，兴言夕放闲。","携琴仙洞中，置酒㴩湖上。","芳景恣行乐，谪居忽如忘。","聚散本相因，离情自悲怅。","鸾翮非常戢，鹏天会昭旷。","永怀宛洛游，曾是弹冠望。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5c4020cb-b7e6-42dc-9f05-e153d36a755d","tags":[]},{"id":"poem-7a7a591e238139c202bcc3e3","title":"赤霄行","author":"杜甫","dynasty":"唐","verses":["孔雀未知牛有角，渴饮寒泉逢觝触。","赤霄悬圃须往来，翠尾金花不辞辱。","江中淘河吓飞燕，衔泥却落羞华屋。","皇孙犹曾莲勺困，卫庄见贬伤其足。","老翁慎莫怪少年，葛亮贵和书有篇。","丈夫垂名动万年，记忆细故非高贤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3c55ddde-5ba6-4c4a-868d-a1741df7c270","tags":[]},{"id":"poem-7a7e47893bc29b52bf50299c","title":"景仁将归颖昌輙为诗二十韵纪赠","author":"司马光","dynasty":"宋","verses":["秀发西南美，挺生河岳灵。","雕龙蔚文采，老鸖莹仪形。","落笔高时隽，飞緌侍帝庭。","英声轶云汉，远势击沧溟。","苦节专忧国，嘉谋毎据经。","温虽比圭璧，直不避雷霆。","道胜轩裳薄，神和气体宁。","忠诚怀畎亩，乐事寄林坰。","藻鉴评随月，过从德应星。","苦吟金出矿，确论木衔钉。","贱子叨流辈，高风仰典刑。","巨川容滴水，余景借流萤。","久别眉俱白，重来眼更青。","淹留弦与晦，游集醉还醒。","有酒须相就，无歌不共聼。","奇花喧夕市，叠鼓咽春亭。","扬袂行辞洛，回车去望陉。","往还天表鴈，离合浪间萍。","异日期同传，穷泉约互铭。","古今难得事，交分保颓龄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-40fe28a9-2393-4836-83ea-c79aab7f4ef9","tags":[]},{"id":"poem-7a7eda1d99d7c10966499fcd","title":"句","author":"唐求","dynasty":"唐","verses":["恰似有龙深处卧，被人惊起黑云生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-19bd9a22-3b09-4240-95dd-f774dfaa08ca","tags":[]},{"id":"poem-7a81292d133f7e53d412777a","title":"遥伤茅山县孙尊师三首 一","author":"李德裕","dynasty":"唐","verses":["蝉蜕遗虚白，蜺飞入上清。","同人悲劒解，旧友觉衣轻。","黄鹄遥将举，斑麟俨未行。","惟应鲍靓室，中夜识琴声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7fd2e15e-24c5-47bd-83a4-4e3fe7384ddd","tags":[]},{"id":"poem-7a8403f3a396f3afad1028e7","title":"咏小瀑布","author":"皎然","dynasty":"唐","verses":["瀑布小更奇，潺湲二三尺。","细脉穿乱沙，丛声咽危石。","初因智者赏，果会幽人迹。","不向定中闻，那知我心寂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c0e7fc56-c2c2-4369-9056-a8a2c2eb5b59","tags":[]},{"id":"poem-7a8548fbd47f8bbbd2145020","title":"晁端州秀宴席","author":"刘跂","dynasty":"宋","verses":["同寮贵公子，好事敌原尝。","晁侯更萧散，不爱囊中装。","步兵玉觥滑，洞庭金丸香。","宛转莼带细，纷纶鲙缕长。","鳆鱼三百饤，岂必河之鲂。","咄嗟事便办，侍御色不忙。","熙熙春台上，醉语各相忘。","汤餠最后出，虽饱别有肠。","愿君善遇客，懽乐殊未央。","不须投车辖，敬举主人觞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8199df0b-bd68-4f10-901e-14edd7aa2043","tags":["洞庭湖"]},{"id":"poem-7a8ae1642edd29cc34d47f8e","title":"前腔换头","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["今后，方信你彻底澄清，我好没来由。","(贴白)你怎的不收拾了心下？(丑唱)想象暮云，分付东风，情到不堪回首。","(贴白)你怎不学我？(丑唱)听剖：你是蕊宫琼苑神仙，不比尘凡相诱。","(贴白)恁地，自随我习些女工便了。","(丑唱)谨随侍，窗下拈针挑绣。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4928","tags":[]},{"id":"poem-7a8be4197610e4ae081d351d","title":"述梦诗四十韵","author":"李德裕","dynasty":"唐","verses":["赋命诚非薄，良时幸已遭。","君当尧舜日，官接凤皇曹。","目睇烟霄阔，心惊羽翼高。","椅梧连鹤禁，壀堄接龙韬。","我后怜词客，吾僚并隽髦。","著书同陆贾，待诏比王褒。","重价连悬璧，英词淬宝刀。","泉流初落涧，露滴更濡毫。","赤豹欣来献，彤弓喜暂櫜非烟含瑞气，驯雉洁霜毛。","静室便幽独，虚楼散郁陶。","花光晨艳艳，松韵晚骚骚。","画壁看飞鹤，仙图见巨鼇。","倚簷阴药树，落格蔓蒲桃。","荷静蓬池鲙，冰寒郢水醪。","荔枝来自远，卢橘赐仍叨。","麝气随兰泽，霜华入杏膏。","恩光惟觉重，携挈未为劳。","夕阅梨园骑，宵闻禁杖獒。","扇回交彩翟，雕起飏银绦。","辔待袁丝揽，书期蜀客操。","尽规常謇謇，退食尚忉忉。","龟顾垂金钮，鸾飞曳锦袍。","御沟杨柳弱，天廐骕骦豪。","屡换青春直，闲随上苑遨。","烟低行殿竹，风拆绕墙桃。","聚散俄成昔，悲愁益自熬。","每怀仙驾远，更望茂陵号。","地接三茅岭，川迎伍子涛。","花迷瓜步暗，石固蒜山牢。","兰野凝香管，梅洲动翠篙。","泉鱼惊彩妓，溪鸟避干旄。","感旧心犹绝，思归首更搔。","无聊燃[蜜]炬，谁复劝金舠。","岚气朝生栋，城阴夜入濠。","望烟归海峤，送鴈渡江臯。","宛马嘶寒枥，吴钩在锦弢。","未能追狡兔，空觉长黄蒿。","水国逾千里，风帆过万艘。","阅川终古恨，惟见暮滔滔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8b41c002-e220-45f6-b816-c8f499e39622","tags":[]},{"id":"poem-7a8e8a6e3a43f0f886870220","title":"蓟门行五首 五","author":"高适","dynasty":"唐","verses":["黯黯长城外，日没更烟尘。","胡骑虽凭陵，汉兵不顾身。","古树满空塞，黄云愁杀人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6145d02d-f6db-4a7e-be04-03535abd63c3","tags":[]},{"id":"poem-7a91e2cbbee78603010696c1","title":"李舍人山园送庞邵","author":"沈佺期","dynasty":"唐","verses":["符传有光辉，諠諠出帝畿。","东隣借山水，南陌驻骖𬴂。","握手凉风至，当歌秋日微。","高幨去勿缓，人吏待霜威。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0c70f20d-13fe-412e-8f42-c5a39ee16831","tags":[]},{"id":"poem-7a92ccbd786cd5727e5b6517","title":"十二月","author":"杨景贤","dynasty":"元","verses":["这声响似春雷降临，火炮相侵，惊得冰肌凛凛，冷汗浸浸。","不见了宋玉多才的翰林，撇下这巫娥美貌难禁。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4509","tags":[]},{"id":"poem-7a933843e371a7705af0b1af","title":"早登太行山中言志","author":"明皇帝","dynasty":"唐","verses":["清跸度河阳，凝笳上太行。","火龙明鸟道，铁骑绕羊肠。","白雾埋阴壑，丹霞助晓光。","涧泉含宿冻，山木带余霜。","野老茅为屋，樵人薜作裳。","宣风问耆艾，敦俗劝耕桑。","凉德慙先哲，徽猷慕昔皇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5b721d41-b555-48ff-8c1d-c81104498e39","tags":[]},{"id":"poem-7a93467910be7827f732ecb2","title":"碧流院（题拟）","author":"杜棱","dynasty":"唐","verses":["石骨生泉冷，流来涧沼湄。","幽禽鸣竹砌，游客步阶陲。","滃郁杉松碧，阴稠烟霭缁。","古风吟不足，嗟恨老苍髭。","（见宋潜说友《咸淳临安志》卷八十五。","）（按：碧流院，吴越王更名碧沼。","此诗不详作年，题仍旧名。","又棱约卒于干宁、天复间，以其为钱镠佐属，故收归吴越。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-bc5bcd61-07e0-4b16-b56d-8265a2c13fa8","tags":[]},{"id":"poem-7a9e1543efb2a26141154b09","title":"冬夕","author":"张籍","dynasty":"唐","verses":["寒蛩独罢织，湘雁犹能鸣。","月色当窗入，乡心半夜生。","不成高枕梦，复作遶堦行。","回首嗟淹泊，城头北斗横。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-bf5cb147-b653-4297-8569-0d487601292f","tags":[]},{"id":"poem-7aa3d135ff81f4041649920e","title":"兵要望江南 占梦第二十五（京本列第十三○九首） 三","author":"易静","dynasty":"唐","verses":["将军梦，鱼变作蛟龙。","百战自然皆百胜，相敌来捉必无凶，大将职加封。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4db9fa18-e023-462e-9cf9-c56bcc3abc4d","tags":[]},{"id":"poem-7aad2e9181cb8d8a8caff54b","title":"潇湘游","author":"刘言史","dynasty":"唐","verses":["夷女采山蕉，缉纱浸江水。","野花满髻妆色新，闲歌[欸]乃深峡里。","[欸]乃知从何处生，当时泣舜肠断声。","翠华寂寞婵娟没，野筿空余红泪情。","青烟冥冥覆杉桂，崖壁凌天风雨细。","昔人幽恨此地遗，绿芳红艳含怨姿。","清猨未尽鼯鼠切，泪水流到湘妃祠。","北人莫作潇湘游，九疑云入苍梧愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6f8b1f28-3851-4b7f-bd62-2b63eb67793d","tags":[]},{"id":"poem-7ab70f51511dffa2baa3ae49","title":"竹竿","author":"佚名","dynasty":"先秦","verses":["籊籊竹竿，以钓于淇。岂不尔思？远莫致之。","泉源在左，淇水在右。女子有行，远兄弟父母。","淇水在右，泉源在左。巧笑之瑳，佩玉之傩。","淇水滺滺，桧楫松舟。驾言出游，以写我忧。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-58","tags":[]},{"id":"poem-7ab8dc04c71a2bd321bbec19","title":"浣溪沙·消息谁传到拒霜","author":"纳兰性德","dynasty":"清","verses":["消息谁传到拒霜。","两行斜雁碧天长。","晚秋风景倍凄凉。","银蒜押帘人寂寂，玉钗敲竹信茫茫。","黄花开也近重阳。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-109","tags":[]},{"id":"poem-7ac415dafac3b435cef2ae16","title":"河满子·红粉楼前月照","author":"毛文锡","dynasty":"五代","verses":["红粉楼前月照，碧纱窗外莺啼。","梦断辽阳音信，那堪独守空闺。","恨对百花时节，王孙绿草萋萋。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-31","tags":[]},{"id":"poem-7ac95f2cca3bdc6f2ae223d5","title":"书怀","author":"于邺","dynasty":"唐","verses":["长安多路岐，西去欲何依。","浮世祗如此，旧山长忆归。","自离京国久，应已故人稀。","好与孤云住，孤云无是非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b9dc6a94-5846-4660-97ee-eee857c53cb2","tags":[]},{"id":"poem-7acc763fd4a7ffc1e8a1a7f4","title":"·（《涉道诗》二十八首〖伯三八六六〗）","author":"李翔","dynasty":"唐","verses":["（《涉道诗》二十八首〖伯三八六六〗）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f54266ff-9369-4655-920c-9a56a2a06417","tags":[]},{"id":"poem-7ad19551b7a6256235da7c09","title":"南楼令·塞外重九","author":"纳兰性德","dynasty":"清","verses":["古木向人秋，惊蓬掠鬓稠。","是重阳、何处堪愁。","记得当年惆怅事，正风雨，下南楼。","断梦几能留，香魂一哭休。","怪凉蝉、空满衾裯。","霜落乌啼浑不睡，偏想出，旧风流。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-133","tags":[]},{"id":"poem-7ad86bee9a6852eb3aad9554","title":"小游仙诗九十八首 六十二","author":"曹唐","dynasty":"唐","verses":["闻君新领八霞司，此别相逢是几时。","妾有一觥云母酒，请君终宴莫推辞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b22b2fbd-3001-46b0-bec3-d140ba97bc5c","tags":[]},{"id":"poem-7ad894198c740efc109d48eb","title":"挽汪约叟  其一","author":"王柏","dynasty":"宋","verses":["幸有灵光在，天乎作么亡。","生来最真实，病里亦康强。","和气留丹鼎，清尘凝笔床。","溪山呈秀处，风露悄凄凉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-6fcb241a-6036-47dc-98d2-247fe4bfc725","tags":[]},{"id":"poem-7ad9194f3b3a4e8dc91f71c2","title":"墓门","author":"佚名","dynasty":"先秦","verses":["墓门有棘，斧以斯之。夫也不良，国人知之。知而不已，谁昔然矣。","墓门有梅，有鸮萃止。夫也不良，歌以讯之。讯予不顾，颠倒思予。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-140","tags":[]},{"id":"poem-7ae49fd4023cbc74f90b9589","title":"唐明堂乐章 配飨","author":"则天皇后","dynasty":"唐","verses":["笙镛间玉宇，文物昭清辉。","晬影临芳奠，休光下太微。","孝思期有感，明絜庶无违。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-9f23da9b-b91b-4673-b628-562e0a371b16","tags":[]},{"id":"poem-7aea12252e2f9bdb3285ae90","title":"送淡公 九","author":"孟郊","dynasty":"唐","verses":["报恩兼报德，寺与山争鲜。","橙橘金盖槛，竹蕉绿凝禅。","经章音韵细，风磬清泠翩。","离肠绕师足，旧忆随路延。","不知几千尺，至死方绵绵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3b7aa17e-5f9f-428e-adc6-b8f4c8643ab6","tags":[]},{"id":"poem-7af8adb45b11724fb201c840","title":"桃花谿","author":"张旭","dynasty":"唐","verses":["隐隐飞桥隔野烟，石矶西畔问渔船。","桃花尽日随流水，洞在清谿何处边。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1f28ab03-8388-4a2f-8c4f-3ce47789e221","tags":["唐诗三百首","描写水","写景","抒情","七言绝句","写水"]},{"id":"poem-7afac4310fbc88ef7e4a49c8","title":"过浯溪","author":"米芾","dynasty":"宋","verses":["胡羯自干纪，唐纲竟不维。","可怜德业浅，有愧此碑词。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-ead0f25a-a569-43c7-b95c-e8037447c9ce","tags":[]},{"id":"poem-7b00e93ea11920b9289ce114","title":"清平乐·参横月落","author":"纳兰性德","dynasty":"清","verses":["参横月落，客绪从谁托。","望里家山云漠漠，似有红楼一角。","不如意事年年，消磨绝塞风烟。","输与五陵公子，此时梦绕花前。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-165","tags":[]},{"id":"poem-7b04db6ad8125df59a0aab90","title":"小重山·春到长门春草青","author":"薛昭蕴","dynasty":"五代","verses":["春到长门春草青，玉阶华露滴，月胧明。","东风吹断紫箫声，宫漏促，帘外晓啼莺。","愁极梦难成，红妆流宿泪，不胜情。","手挼裙带绕阶行，思君切，罗幌暗尘生。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-37","tags":[]},{"id":"poem-7b0720642ff50803aaeb618a","title":"答鄱阳客药名诗","author":"张籍","dynasty":"唐","verses":["江臯岁暮相逢地，黄叶霜前半夏枝。","子夜吟诗向松桂，心中万事喜君知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c0cbb0bd-9129-48c9-aef6-c116139328cc","tags":[]},{"id":"poem-7b0aced023ab9d834f25f76e","title":"忆秦娥·十五六","author":"欧阳修","dynasty":"宋","verses":["十五六，脱罗裳，长恁黛眉蹙。","红玉暖，入人怀，春困熟。","展香裀，帐前明画烛。","眼波长，斜浸鬓云绿。","看不足。","苦残宵、更漏促。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-815","tags":[]},{"id":"poem-7b1373950b424194fe7f2c84","title":"题故僧影堂","author":"张籍","dynasty":"唐","verses":["香消云锁旧僧家，僧刹残形半壁斜。","日暮松烟寒漠漠，秋风吹破纸莲花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e979ddc0-7d65-46c3-bb3a-10a65869481c","tags":[]},{"id":"poem-7b18ed694a7aad811266db43","title":"忆鹤","author":"刘得仁","dynasty":"唐","verses":["自尔归仙后，经秋又过春。","白云寻不得，紫府去无因。","此地空明月，何山伴羽人。","终期华表上，重见令威身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a239c65c-e5e0-4463-b314-ce56f0a3fac4","tags":[]},{"id":"poem-7b1a2be83159747bda10371b","title":"醉公子·岸柳垂金线","author":"顾敻","dynasty":"五代","verses":["岸柳垂金线，雨晴莺石啭。","家在绿杨边，往来多少年。","马嘶芳草远，高楼帘半卷。","敛袖翠蛾攒，相逢尔许难。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-35","tags":[]},{"id":"poem-7b263da2c2df0de5b068d030","title":"王成之太博寄诗病中未能和谩书二十字以酬","author":"王十朋","dynasty":"宋","verses":["老病欲纳禄，君恩许奉祠。","已为三径计，误辱广文诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4c466f19-dcea-496f-b3fc-86840642a607","tags":[]},{"id":"poem-7b30d35b9a74c482c605aed9","title":"点绛唇·孤馆迢迢","author":"周邦彦","dynasty":"宋","verses":["孤馆迢迢，暮天草露沾衣润。","夜来秋近。","月晕通风信。","今日原头，黄叶飞成阵。","知人闷。","故来相趁。","共结临岐恨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-419","tags":[]},{"id":"poem-7b30e2257d354c0f8cd7f474","title":"寓意","author":"李咸用","dynasty":"唐","verses":["直道荆棘生，斜径红尘起。","苍苍杳无言，麒麟回瑞趾。","东风如未来，飞雪终不已。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8246838a-99ce-49e5-bf69-3ce37023549d","tags":[]},{"id":"poem-7b4b068e0396b8f194b22161","title":"题云际寺暕上人故院","author":"李端","dynasty":"唐","verses":["白发怱怱色，青山草草心。","远公仍下世，从此别东林。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0b4365f7-5f12-44bf-aef1-b30e2762fe41","tags":[]},{"id":"poem-7b4f14d39b19496ec6185039","title":"浣溪沙·举案家风未肯低","author":"仲并","dynasty":"宋","verses":["举案家风未肯低。","清心端自秀深闺。","芝兰玉树宁馨儿。","早岁安禅灵照女，静中经卷手常携。","声名要与断机齐。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-180","tags":[]},{"id":"poem-7b5fb34d3787bf3494dc2eb7","title":"偈 九","author":"契此","dynasty":"唐","verses":["圆觉灵明超太虚，目前万物不差殊。","十方法界都包尽，惟有真如也太迂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b5089859-5bec-4d0b-ae5f-94efe8342e2a","tags":[]},{"id":"poem-7b61036a658b77c7df8e6845","title":"哭张文翁同舍  其一","author":"赵文","dynasty":"宋","verses":["岂意渴相如，俄为化子舆。","平生一杯酒，活计百篇书。","同舍遂欲尽，吾生不愿余。","如今念夫子，痛饮未全疏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-356db575-8301-441d-a22d-fe4dc4c62e3b","tags":[]},{"id":"poem-7b6ade38b49d2072c11a70d4","title":"军山前马退石","author":"李翔","dynasty":"唐","verses":["山亘南丰石亘山，石横山路马登难。","非论蹇步须回驾，纵使追风亦解鞍。","恐是龙宫通洞府，莫应猿岭建星坛。","何因不许超骧辈，踏着连云大麓端。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-28958c31-0d3d-4757-bbf3-0511f02f2c03","tags":[]},{"id":"poem-7b6e2345e27f75c9f145520d","title":"春秋战国门 隐公","author":"周昙","dynasty":"唐","verses":["今古难隄是小人，苟希荣宠任相亲。","陈谋不信怀忧惧，反间须防却害身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-dc2e934a-6d91-4849-9d45-167a1d92454b","tags":[]},{"id":"poem-7b75342d8bf1adfe4ff0d00d","title":"九思·疾世","author":"王逸","dynasty":"汉","verses":["周徘徊兮汉渚，求水神兮灵女。","嗟此国兮无良，媒女诎兮謰謱。","𫛩雀列兮哗讙，鸲鹆鸣兮聒余。","抱昭华兮宝璋，欲衒鬻兮莫取。","言旋迈兮北徂，叫我友兮配耦。","日阴曀兮未光，阒睄窕兮靡睹。","纷载驱兮高驰，将谘询兮皇羲。","遵河皋兮周流，路变易兮时乖。","濿沧海兮东游，沐盥浴兮天池。","访太昊兮道要，云靡贵兮仁义。","志欣乐兮反征，就周文兮邠歧。","秉玉英兮结誓，日欲暮兮心悲。","惟天禄兮不再，背我信兮自违。","逾陇堆兮渡漠，过桂车兮合黎。","赴昆山兮馽𫘧，从邛遨兮栖迟。","吮玉液兮止渴，啮芝华兮疗饥。","居嵺廓兮尠畴，远梁昌兮几迷。","望江汉兮濩渃，心紧絭兮伤怀。","时昢昢兮且旦，尘莫莫兮未晞。","忧不暇兮寝食，咤增叹兮如雷。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-58","tags":[]},{"id":"poem-7b7ed6e02084df9431580821","title":"牵牛织女","author":"杜甫","dynasty":"唐","verses":["牵牛出河西，织女处其东。","万古永相望，七夕谁见同。","神光意难候，此事终蒙胧。","飒然精灵合，何必秋遂通。","亭亭新妆立，龙驾具曾空。","世人亦为尔，祈请走儿童。","称家随丰俭，白屋达公宫。","膳夫翊堂殿，鸣玉凄房栊。","曝衣徧天下，曳月扬微风。","蛛丝小人态，曲缀瓜果中。","初筵裛重露，日出甘所终。","嗟汝未嫁女，秉心郁忡忡。","防身动如律，竭力机杼中。","虽无姑舅事，敢昧织作功。","明明君臣契，咫尺或未容。","义无弃礼法，恩始夫妇恭。","小大有佳期，戒之在至公。","方圆苟龃龉，丈夫多英雄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-449c81fd-d52a-40f2-ae8c-9d3fc5ddd290","tags":[]},{"id":"poem-7b7fade54f56e70ed941b719","title":"寄郑良佐","author":"陈造","dynasty":"宋","verses":["书生著书贪日课，文士卖文救穷饿。","青楼歌酒属富儿，不意此名君乃荷。","风波平地自谁始，一倡从知百人和。","东鲁男子旧踪谨，南郡诸生底逋播。","平安敢烦街吏报，洁白长赓楚人些。","流言不计两曾参，机上慈亲枉惊堕。","阮舍尤须辨南北，杜冠可无分小大。","宁知宋玉笑登徒，或指宣尼作阳货。","璧亡误使张仪去，兵利徒为少卿祸。","违从兄食祇厚诬，偿同舍金聊引过。","无黥可息劓可补，未信白璧青蝇涴。","君不见吾宗孟公士所倾，亦有俗子惊人坐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ac4d54d2-ffcc-4736-8294-c58dc1aea68e","tags":[]},{"id":"poem-7b8045ebb1ba92e20536070d","title":"挽曹叔献","author":"王柏","dynasty":"宋","verses":["野草何青青，野花亦莙莙。","王园翳烟树，东风开泉扃。","灵辰倏祥练，祖载何因循。","半生安陋巷，箪瓢澹无营。","天命有穷达，书生多苦辛。","北邙同一路，玄庐等枯荣。","我本里中子，升堂托微婣。","每怀桮渡语，惟士有常心。","几杖虽疏阔，睠睠敬爱深。","故家乔木瘁，不复典刑存。","流水桃花窅，飘零薤露音。","幽宫一以閟，清泪洒芳春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-743df558-8344-4551-97aa-86fec74ed474","tags":[]},{"id":"poem-7b8a1b41cebc993d4d52816c","title":"游仙窟诗 别十娘","author":"张文成","dynasty":"唐","verses":["忽然闻道别，愁来不自禁。","眼下千行泪，肠悬一寸心。","两劒俄分匣，双凫忽异林。","慇懃惜玉体，勿使外人侵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-aab30de0-434f-42ce-809c-ce09462c7d66","tags":[]},{"id":"poem-7b9200216ba5eac7d3be9729","title":"洋州三十景 吏隐亭","author":"鲜于侁","dynasty":"宋","verses":["心休忘物我，道胜一轩静。","隐几度朝晡，可嗟人畏影。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-697ceb6d-33a6-4b51-ad1a-f9133d552cdd","tags":[]},{"id":"poem-7b9347a3a54828da0d842340","title":"甘州歌","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["衷肠闷损，叹路途千里，日日思亲。","青梅如豆，难寄陇头音信。","高堂已添双鬓雪，俺客路空瞻一片云。","(合)途中味，客里身，争如流水蘸柴门？休回首，欲断魂，数声啼鸟不堪闻。","(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4971","tags":[]},{"id":"poem-7ba022ead03c45c08798512d","title":"生民","author":"佚名","dynasty":"先秦","verses":["厥初生民，时维姜嫄。生民如何？克禋克祀，以弗无子。","履帝武敏歆，攸介攸止，载震载夙。载生载育，时维后稷。","诞弥厥月，先生如达。不拆不副，无菑无害。以赫厥灵。","上帝不宁，不康禋祀，居然生子。","诞寘之隘巷，牛羊腓字之。诞寘之平林，会伐平林。","诞寘之寒冰，鸟覆翼之。鸟乃去矣，后稷呱矣。","实覃实𬣙，厥声载路。诞实匍匐，克岐克嶷。以就口食。","蓺之荏菽，荏菽旆旆。禾役穟穟，麻麦幪幪，瓜瓞唪唪。","诞后稷之穑，有相之道。茀厥丰草，种之黄茂。实方实苞，实种实褎。","实发实秀，实坚实好。实颖实栗，即有邰家室。","诞降嘉种，维秬维秠，维穈维芑。恒之秬秠，是获是亩。","恒之穈芑，是任是负。以归肇祀。","诞我祀如何？或舂或揄，或簸或蹂。释之叟叟，烝之浮浮。","载谋载惟。取萧祭脂，取羝以軷，载燔载烈，以兴嗣岁。","卬盛于豆，于豆于登。其香始升，上帝居歆。胡臭亶时。","后稷肇祀。庶无罪悔，以迄于今。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-244","tags":[]},{"id":"poem-7bab5e58dd3684223d10f578","title":"周先生画洞庭歌","author":"鲍溶","dynasty":"唐","verses":["江南客，水为乡，舟为宅，能以笔锋知地脉。","闲分楚水入丹青，不下此堂临洞庭。","水文不浪烟不动，木末棱棱山碧重。","帝子应哀窈窕云，客人似得婵娟梦。","六月火光衣上生，斋心寂听潺湲声。","林冰摇镜水拂簟，尽日独卧秋风清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-29e61c7a-6386-478d-a35f-81ea451bce21","tags":["洞庭湖"]},{"id":"poem-7babe4d41015f2d78b2cdd45","title":"破山寺后禅院","author":"常建","dynasty":"唐","verses":["清晨入古寺，初日照高林。","曲径通幽处，禅房花木深。","山光悦鸟性，潭影空人心。","万籁此俱寂，惟闻钟磬音。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-破山寺後禪院","tags":[]},{"id":"poem-7bb7756c372ee6e90846344e","title":"美人宫棋","author":"张籍","dynasty":"唐","verses":["红烛台前出翠娥，海沙铺局巧相和。","趂行移手巡收尽，数数看谁得最多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-12ee9d91-c4af-467a-90cd-ad6857e7f96f","tags":[]},{"id":"poem-7bbb8ff885e1495d5ba0addd","title":"月下喜邢校书至自洛","author":"李益","dynasty":"唐","verses":["天河夜未央，漫漫复苍苍。","重君远行至，及此明目光。","华星暎衰柳，暗水入寒塘。","客心定何似，余欢方自长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a47b1955-1d2d-4229-abd2-13f63dc48b33","tags":[]},{"id":"poem-7bc64d3c86ce4bf52ded0234","title":"临江仙·孤雁","author":"纳兰性德","dynasty":"清","verses":["霜冷离鸿惊失伴，有人同病相怜。","拟凭尺素寄愁边，愁多书屡易，双泪落灯前。","莫对月明思往事，也知消减年年。","无端嘹唳一声传，西风吹只影，刚是早秋天。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-102","tags":[]},{"id":"poem-7bcc57f1a37ecb7d125bf43c","title":"晚秋","author":"王同祖","dynasty":"宋","verses":["世变无穷客恨长，栏干遍倚怕斜阳。","满篱黄菊无心看，付与游蜂自在忙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-5e4eb46f-54c3-4932-9d4b-f5b072e3a030","tags":[]},{"id":"poem-7bd468af2f3ca3ed0c9f3baa","title":"四园竹·花骢纵策","author":"方千里","dynasty":"宋","verses":["花骢纵策，制泪掩斜扉。","玉炉细袅，鸳被半闲，萧瑟罗帏。","银漏声，那更杂、疏疏雨里，此时怀抱谁知。","恨凄其。","西窗自剪寒花，沈吟暗数归期。","最爱深情密意，无限当年，往复诗辞。","千万纸。","甚近日、人来字渐稀。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-528","tags":[]},{"id":"poem-7bd83df033d6d75ea26d8ad1","title":"同萧炼师宿太乙庙","author":"李益","dynasty":"唐","verses":["微月空山曙，春祠谒少君。","落花坛上拂，流水洞中闻。","酒引芝童奠，香余桂子焚。","鹤飞将羽节，遥向赤城分。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-bd1f5183-318f-40d2-ac1c-fe5b12415a25","tags":[]},{"id":"poem-7bdaf6ef2815216789f79d29","title":"游月陂","author":"程颢","dynasty":"宋","verses":["月坡堤上四徘徊，北有中天百尺台。","万物已随秋气改，一樽聊为晚凉开。","水心云影闲相照，林下泉声静自来。","世事无端何足计，但逢佳节约重陪。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-遊月陂","tags":[]},{"id":"poem-7bdcbdc3aa8a47da0833cc8a","title":"风入松·一春长费买花钱","author":"俞国宝","dynasty":"宋","verses":["一春长费买花钱。","日日醉花边。","玉骢惯识西湖路，骄嘶过、沽酒垆前。","红杏香中箫鼓，绿杨影里秋千。","暖风十里丽人天。","花压髻云偏。","画船载取春归去，馀情寄、湖水湖烟。","明日重扶残醉，来寻陌上花钿。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-177","tags":["宋词三百首","西湖"]},{"id":"poem-7bdde93ba7e165da930e2256","title":"月夜","author":"杜甫","dynasty":"唐","verses":["今夜鄜州月，闺中只独看。","遥怜小儿女，未解忆长安。","香雾云鬟湿，清辉玉臂寒。","何时倚虚幌，双照泪痕干。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-59c7eaa9-3c05-4857-8cff-10376706ccb9","tags":["唐诗三百首","思念","女子","五言律诗","高中古诗","月亮","三年级上册"]},{"id":"poem-7bde37d258d845c5b4493426","title":"蕙香囊・鹊桥仙·身作琵琶","author":"欧阳修","dynasty":"宋","verses":["身作琵琶，调全宫羽，佳人自然用意。","宝檀槽在雪胸前，倚香脐、横枕琼臂。","组带金钩，背垂红绶，纤指转弦韵细。","愿伊只恁拨梁州，且多时、得在怀里。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-818","tags":[]},{"id":"poem-7bdf32a9326bbaa9ee75d5ce","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(丑)小梅香，待回言，恐触突了使长。","不回言，这无情棒打难当，怎知道祸从天降。","他本是守荆钗寒门孟光。","(外)潜奔之女，什么孟光！(丑)休错认做出墙花淮甸双双。","我说起这行藏。","(外)说什么来？(丑)他说道：烧香的王太守，好似亡夫模样。","寻思痛感伤，因此上和妾在此闲讲，又个曾想像赴高唐。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8340","tags":[]},{"id":"poem-7bf4861ec523ee6ea56ca00b","title":"宫使蔡太师寿诗","author":"华镇","dynasty":"宋","verses":["天贻真宰赞重熙，何日来符命世期。","五夜燕游元夕后，三阳交泰上春时。","维师事业前无吕，先觉心灵世有伊。","首斡化机熙帝载，暂休祠馆动民思。","和羹终付盐梅手，仗节难稽柱石姿。","华屋早开丞相第，衮衣新赋我公诗。","缃桃满院光风转，素李成蹊淑景迟。","鼎席具瞻何所愿，祝公眉寿等莲龟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-86c8d79c-06c0-4051-bdfa-aa84d80c20a9","tags":[]},{"id":"poem-7bf9d6286437ff405f55cc40","title":"凭远亭","author":"赵崇嶓","dynasty":"宋","verses":["莎庭日日报平安，幽处依然绝往还。","平野四围天一幅，有人踏雪看南山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-59efc573-a2e7-45fc-9cf0-216a25e8d818","tags":[]},{"id":"poem-7c03be812f13e10dde20f328","title":"宝鼎现·红妆春骑","author":"刘辰翁","dynasty":"宋","verses":["红妆春骑。","踏月影、竿旗穿市。","望不尽、楼台歌舞，习习香尘莲步底。","箫声断、约彩鸾归去，未怕金吾呵醉。","甚辇路、喧阗且止。","听得念奴歌起。","父老犹记宣和事。","抱铜仙、清泪如水。","还转盼、沙河多丽。","漾明光连邸第。","帘影冻、散红光成绮。","月浸葡萄十里。","看往来、神仙才子。","肯把菱花扑碎。","肠断竹马儿童，空见说、三千乐指。","等多时春不归来，到春时欲睡。","又说向、灯前拥髻。","暗滴鲛珠坠。","便当日、亲见霓裳，天上人间梦里。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-90","tags":["宋词三百首"]},{"id":"poem-7c06f486d8715ab86aaa5fa2","title":"秋末入匡山船行八首 八","author":"贯休","dynasty":"唐","verses":["晓色千樯去，长江八月时。","雨淙山骨出，橰擉岸形卑。","野水畬田黑，荒汀独鸟痴。","如今是清世，谁道出山迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c8a79701-1203-4814-8657-c7aa5a0c55b6","tags":["庐山","长江"]},{"id":"poem-7c099062e98c75b2aec40b5d","title":"观搊筝","author":"王湾","dynasty":"唐","verses":["虚室有秦筝，筝新月复清。","弦多弄委曲，柱促语分明。","晓怨凝繁手，春娇入曼声。","近来唯此乐，传得美人情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ea4b6d44-baf2-4afc-9554-c48284940ccc","tags":[]},{"id":"poem-7c09f578a2965e6483abff70","title":"尾声","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(众)今朝共合为姻眷，美满大妻共百年，双双齐效鹣鹣。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8926","tags":[]},{"id":"poem-7c0bb796c45321abc05c20c7","title":"短歌行","author":"冯著","dynasty":"唐","verses":["寂寞草中兰，亭亭山上松。","贞芳日有分，生长耐相容。","结根各得地，幸沾雨露功。","参辰无停泊，且顾一西东。","君但开怀抱，猜恨莫怱怱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-90a5027b-b4c8-4f7b-a79a-0590bbba125d","tags":[]},{"id":"poem-7c0efa40e3802c6707956e7f","title":"乙巳冬十月随幼男赴海陵丞中途遇交代有开正视事之请既抵官舍有作","author":"孙介","dynasty":"宋","verses":["整棹姚江到海陵，稽徊四十日行程。","相逢既诺交承约，少待何妨信义明。","戚戚已无终岁虑，琅琅先有诵书声。","夫妻白首皆天幸，三乐无惭好弟兄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-90c9e8ec-437e-45db-b312-2c0c26bbe3b6","tags":[]},{"id":"poem-7c17cfc0d634326575b46879","title":"八声甘州·化工多事了","author":"黄裳","dynasty":"宋","verses":["化工多事了，却收天巧，都与西风。","数峰云如扫，闲垂六幕，初见秋容。","昨夜烦襟顿释，一雨洗遥空。","偏有银蟾好，千里人同。","引起游人多感，为静中景色，悲思无穷。","傍雕栏怀古，谁问紫元翁。","也难逢、金华时候，又岂知、幽会水精宫。","尘缘满，指烟霞去，多在江东。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-621","tags":[]},{"id":"poem-7c1b7b852088b893d3829a1e","title":"菩萨蛮·牛星织女年年别","author":"张先","dynasty":"宋","verses":["牛星织女年年别。","分明不及人间物。","匹鸟少孤飞。","断沙犹并栖。","洗车昏雨过。","缺月云中堕。","斜汉晓依依。","暗蛩还促机。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-381","tags":[]},{"id":"poem-7c24d8c3803156e3764490b2","title":"读庄子六绝句  其六","author":"李纲","dynasty":"宋","verses":["诋欺儒墨每云云，刍狗诗书迹已陈。","泯绝是非归道妙，扫除糠粃见天真。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3ff56629-830d-4802-9ef8-14d306799827","tags":[]},{"id":"poem-7c2c494aefd9bbf95a63c549","title":"侍宴","author":"沈佺期","dynasty":"唐","verses":["皇家贵主好神仙，别业初开云汉边。","山出尽如鸣凤岭，池成不让饮龙川。","妆楼翠幌教春住，舞阁金铺借日悬。","敬从乘舆来此地，称觞献寿乐钧天。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-侍宴","tags":[]},{"id":"poem-7c2c88122caaee9bc83cdc04","title":"中和节赐群臣宴赋七韵","author":"德宗皇帝","dynasty":"唐","verses":["东风变梅柳，万汇生春光。","中和纪月令，方与天地长。","耽乐岂予尚，懿兹时景良。","庶遂亭育恩，同致寰海康。","君臣永终始，交泰符阴阳。","曲沼水新碧，华林桃稍芳。","胜赏信多欢，戒之在无荒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-9f07ad1d-8a95-4e2f-984d-b2f35a057ca6","tags":[]},{"id":"poem-7c3357ffb1b78b4aa052bd57","title":"桃源忆故人·碧天露洗春容净","author":"黄庭坚","dynasty":"宋","verses":["碧天露洗春容净。","淡月晓收残晕。","花上密烟飘尽。","花底莺声嫩。","云归楚峡厌厌困。","两点遥山新恨。","和泪暗弹红粉。","生怕人来问。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-817","tags":[]},{"id":"poem-7c3f45e50075d4696c85db8e","title":"玉交枝","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["别离休叹，我心下非不痛酸。","非爹苦要轻拆散，也只是要图你荣显。","(净唱)蟾宫桂枝须早扳，北堂萱草时光短。","(合)又不知何日再圆？又不知何日再圆？(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4953","tags":[]},{"id":"poem-7c3f4bdaadfcb9dc1078f851","title":"商于逢友人","author":"喻坦之","dynasty":"唐","verses":["行役何时了，年年骨肉分。","春风来汉棹，雪路入商云。","水险溪难定，林寒鸟异群。","相逢聊坐石，啼狖语中闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-5f655743-ad8f-41db-b1cb-a440608023df","tags":[]},{"id":"poem-7c41fe544c799e063d92ba0b","title":"白","author":"无名氏《张协状元》","dynasty":"元","verses":["我底女孩儿，它爹爹是当朝宰执，妈妈是两国夫人，终不成不求得一个好姻缘。","除非嫁个读书人，不问簪缨不问贫。","但愿五湖风月在，不愁无处下丝纶(下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2539","tags":[]},{"id":"poem-7c459332d90e802c466633ab","title":"菩萨蛮·丝丝柳色清愁织","author":"韩淲","dynasty":"宋","verses":["丝丝柳色清愁织。","山城望断花溪碧。","回首仲宣楼。","登临无计愁。","雨声吹海立。","流转韶光急。","九万有鹏程。","沈香天上亭。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-451","tags":[]},{"id":"poem-7c46abb27aed0425e756d93d","title":"扶南曲歌词五首 二","author":"王维","dynasty":"唐","verses":["堂上青弦动，堂前绮席陈。","齐歌卢女曲，双舞洛阳人。","倾国徒相看，宁知心所亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-200e8a61-6549-499e-99f4-3cb6a8172a6d","tags":[]},{"id":"poem-7c48063d0449413063ccc360","title":"题兴化高田院桥亭","author":"郑良士","dynasty":"唐","verses":["到此溪亭上，浮生始觉非。","野僧还惜别，游客亦忘归。","月满千岩静，风清一磬微。","何时脱尘役，杖履愿相依。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-51e55e97-cc29-4408-9fd9-0b20e8c54581","tags":[]},{"id":"poem-7c4ed16a3b5556437c971dd3","title":"观灯玉台体十首  其一○","author":"徐铉","dynasty":"宋","verses":["日照花，七香车。","歌舞平阳第，经过赵李家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-02f2f7e7-3266-4ec8-acc4-ded38a2bb833","tags":[]},{"id":"poem-7c4ed6c1a4a029b097c11586","title":"仙吕/点绛唇","author":"杨景贤","dynasty":"元","verses":["露滴疏杉，雾迷衰柳。","星光淡，秋色将三，皓月如悬鉴。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4495","tags":[]},{"id":"poem-7c50c49f59e724a3cdc3f534","title":"古意呈补阙乔知之","author":"沈佺期","dynasty":"唐","verses":["卢家少妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催木叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁谓含愁独不见，更教明月照流黄。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b9521e2b-963e-4d90-acf3-d87c2a135071","tags":["唐诗三百首","思念","闺怨","乐府"]}];
